# What solc reports for FeeVault: {var: (slot, offset, bytes)}. `feeBps` and
# `maxFee` are `constant` and are ABSENT, which is the fact the second direction
# below rests on.
LAYOUT = {"owner": (0, 0, 20), "feeReceiver": (1, 0, 20)}

PARAMS = [("u", "address"), ("bps", "uint16")]

LADDER = [("owner", "post == pre", "HOLDS"), ("feeReceiver", "post == pre", "HOLDS")]


def make_case():
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(EMITTED)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@FeeVault@F@setDiscount#61", 7)
    assert case is not None, "fixture: the emitted case for enc=7 was not found"
    return em, case


def make_case_target_after_mock():
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(EMITTED_TARGET_AFTER_MOCK)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@Target@F@setFlag#9", 7)
    assert case is not None, "fixture: the emitted case for enc=7 was not found"
    return em, case


def make_case_precompile_ctor():
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(EMITTED_PRECOMPILE_CTOR)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@HyperEVMRateProvider@F@getSpotPriceMultiplier#75", 3)
    assert case is not None, "fixture: the precompile case was not found"
    return em, case


def check(cond, msg):
    """Assert, and say what was checked.

    ⛔ IT RAISES. It used to print `FAIL:` and return 1 into a `bad` counter
    that every test then RETURNED -- and pytest does not read a return value
    (it warns `PytestReturnNotNoneWarning` and passes anyway). MEASURED
    2026-08-22: 1475 checks in this file, one of them failing, and the suite
    reported `512 passed`. A check that cannot fail is not a check.
    """
    if not cond:
        raise AssertionError(msg)
    print(f"ok: {msg}")
    return 0


def test_pin_with_a_slot_is_established():
    """`state.owner == 0` arrives as a PIN and must reach the test."""
    em, case = make_case()
    notes = []
    put, stats = build_put("FeeVault",
                           "setDiscount",
                           7,
                           2,
                           "sol:@C@FeeVault@F@setDiscount#61",
                           region={
                               "bps": (0, 250),
                               "u": (0, (1 << 160) - 1)
                           },
                           holes={},
                           pins={
                               "state.owner": 0,
                               "msg.value": 0
                           },
                           params=PARAMS,
                           emitted=em,
                           case=case,
                           layout=LAYOUT,
                           ladder_rows=LADDER,
                           notes=notes)
    bad = 0
    bad += check(put is not None, "a PUT is produced")
    text = "\n".join(put or [])
    bad += check(stats["state_stored"] == ["state.owner := 0"],
                 f"the pin is established: {stats['state_stored']}")
    bad += check("vm.store(address(c0), bytes32(uint256(0))" in text,
                 "a vm.store at owner's slot 0 is emitted")
    bad += check("PIN state.owner == 0   [ESTABLISHED by vm.store below]" in text,
                 "the header marks the pin ESTABLISHED")
    # msg.value is NOT a state pin and must not grow a store.
    bad += check("PIN msg.value == 0\n" in text + "\n",
                 "a non-state pin keeps its plain header line")
    # The two declared parameters are still lifted -- establishing a pin must
    # not cost the fuzz coordinates.
    bad += check(stats["lifted"] == ["u", "bps"],
                 f"both parameters are still lifted: {stats['lifted']}")
    return bad


def test_relation_establishes_state_from_fuzzed_sender():
    """`state.owner := msg.sender` must share the PUT's pranked sender."""
    em, case = make_case()
    notes = []
    put, stats = build_put("FeeVault",
                           "setDiscount",
                           7,
                           2,
                           "sol:@C@FeeVault@F@setDiscount#61",
                           region={
                               "bps": (0, 250),
                               "u": (0, (1 << 160) - 1),
                               "msg.sender": (1, (1 << 160) - 1)
                           },
                           holes={},
                           pins={"msg.value": 0},
                           params=PARAMS,
                           emitted=em,
                           case=case,
                           layout=LAYOUT,
                           ladder_rows=LADDER,
                           notes=notes,
                           establish=[{
                               "target": "state.owner",
                               "source": "msg.sender"
                           }])
    bad = 0
    bad += check(put is not None, f"a PUT is produced (notes: {notes})")
    text = "\n".join(put or [])
    bad += check("address p_msg_sender" in text, "msg.sender is a fuzzed address parameter")
    bad += check("vm.prank(p_msg_sender);" in text,
                 "the unit call is pranked with the same parameter")
    bad += check("uint256(uint160(p_msg_sender))" in text,
                 "the storage write casts the address source to uint256")
    bad += check(stats["state_stored"] == ["state.owner := msg.sender"],
                 f"the relation is reported as stored: {stats['state_stored']}")
    bad += check(
        stats["established_relations"] == [{
            "target": "state.owner",
            "source": "msg.sender"
        }], f"the relation travels in stats: {stats['established_relations']}")
    return bad


def test_zero_sender_owner_pin_is_promoted_to_executable_relation():
    region = {"notbot": (0, (1 << 160) - 1)}
    holes = {}
    pins = {"msg.sender": 0, "state._owner$49": 0, "state.paused$155": 0}
    state_types = {"_owner": "address", "paused": "bool"}
    state_store_names = {"_owner": "_owner$49", "paused": "paused$155"}
    out_region, out_holes, out_pins, establish, note = (promote_zero_sender_owner_slice(
        region, holes, pins, [], state_types, state_store_names, ["_owner"]))
    bad = 0
    bad += check(out_region["msg.sender"] == (1, (1 << 160) - 1),
                 "zero sender is replaced by a non-zero executable slice")
    bad += check("msg.sender" not in out_pins, "the old zero sender pin is removed")
    bad += check("state._owner$49" not in out_pins,
                 "the old zero owner pin is replaced by a relation")
    bad += check(out_pins.get("state.paused$155") == 0, "unrelated zero state pins are left intact")
    bad += check(establish == [{
        "target": "state._owner$49",
        "source": "msg.sender"
    }], f"owner is established from the pranked sender: {establish}")
    bad += check(note and "re-run over the non-zero sender slice" in note,
                 f"the promotion is auditable: {note}")
    bad += check(
        region == {"notbot": (0, (1 << 160) - 1)} and pins["msg.sender"] == 0 and out_holes == {},
        "the helper returns copies instead of mutating callers")
    return bad


def test_precheck_only_identifies_rendered_width_not_oracle_strength():
    """A point-shaped rendered region may still carry a verifier oracle."""
    em, case = make_case()
    widths = potential_rendered_widths_for_put("setDiscount",
                                               PARAMS,
                                               em,
                                               case,
                                               region={
                                                   "u": (0, 0),
                                                   "bps": (250, 250),
                                                   "state.owner": (0, 10)
                                               },
                                               holes={})
    bad = 0
    bad += check(widths == {
        "u": 1,
        "bps": 1
    }, f"only rendered calldata coordinates count: {widths}")
    bad += check(not any(w > 1 for w in widths.values()),
                 "the precheck can still tell that no rendered coordinate is wide")
    put, stats = build_put("FeeVault",
                           "setDiscount",
                           7,
                           2,
                           "sol:@C@FeeVault@F@setDiscount#61",
                           region={
                               "u": (0, 0),
                               "bps": (250, 250),
                               "state.owner": (0, 10)
                           },
                           holes={},
                           pins={},
                           params=PARAMS,
                           emitted=em,
                           case=case,
                           layout=LAYOUT,
                           ladder_rows=LADDER,
                           notes=[])
    bad += check(
        put is not None and stats["state_asserts"] == 2,
        "a no-wide rendered region still emits a one-point PUT when "
        "the ladder supplies state oracles")
    return bad


def test_no_wide_rendered_coordinate_without_oracle_stays_concrete():
    """No fuzz dimension plus no rendered assertion is not a PUT."""
    em, case = make_case()
    notes = []
    try:
        build_put("FeeVault",
                  "setDiscount",
                  7,
                  2,
                  "sol:@C@FeeVault@F@setDiscount#61",
                  region={
                      "u": (0, 0),
                      "bps": (250, 250)
                  },
                  holes={},
                  pins={},
                  params=PARAMS,
                  emitted=em,
                  case=case,
                  layout=LAYOUT,
                  ladder_rows=[],
                  notes=notes)
    except ConcreteFallback as exc:
        return check("no verifier-backed oracle" in exc.reason,
                     f"the fallback explains the missing oracle: {exc.reason}")
    return check(False, "expected ConcreteFallback")


def test_no_wide_rendered_coordinate_with_only_R0_still_emits_put():
    """R0-only is still a PUT layer; stats keep it separate from R1/R2."""
    em, case = make_case()
    notes = []
    put, stats = build_put("FeeVault",
                           "setDiscount",
                           7,
                           2,
                           "sol:@C@FeeVault@F@setDiscount#61",
                           region={
                               "u": (0, 0),
                               "bps": (250, 250)
                           },
                           holes={},
                           pins={},
                           params=PARAMS,
                           emitted=em,
                           case=case,
                           layout=LAYOUT,
                           ladder_rows=[],
                           notes=notes,
                           exit_kind="normal")
    bad = 0
    bad += check(put is not None, f"R0-only PUT is emitted: {notes}")
    bad += check(stats["oracle_classes"] == ["R0"],
                 f"R0 is recorded as its own oracle layer: {stats}")
    bad += check(stats["exit_kind_asserts"] == 1 and stats["verifier_asserts"] == 0,
                 f"exit-kind and verifier-backed asserts are separate: {stats}")
