def test_empty_bytes_claim_binds_to_its_certified_length_coordinate():
    claim = {
        "inputs": {
            "callee": "0",
            "data": "{ .offset=0, .length=0, .capacity=0, .initialized=1 }",
        },
        "env": {},
        "entry_storage": {},
    }
    expected = {"callee": "0", "data.length": "0"}
    binding, reason = bind_emitted_claim_to_certified_ce(claim,
                                                         expected,
                                                         params=[("callee", "address"),
                                                                 ("data", "bytes memory")])
    bad = 0
    bad += check(binding is not None and reason is None,
                 "an empty bytes witness binds through its exact zero length")
    nonempty = dict(claim)
    nonempty["inputs"] = dict(claim["inputs"], data="{ .length=1 }")
    rejected, rejected_reason = bind_emitted_claim_to_certified_ce(nonempty,
                                                                   expected,
                                                                   params=[("callee", "address"),
                                                                           ("data", "bytes memory")
                                                                           ])
    bad += check(
        rejected is None and "non-scalar" in (rejected_reason or ""),
        f"nonempty bytes remain refused without exact content evidence: {rejected_reason}")
    body = ['    c0.forward(address(uint160(0)), hex"");']
    digest, source_reason = bind_emitted_source_to_certified_ce(body, 0, "forward",
                                                                [("callee", "address"),
                                                                 ("data", "bytes memory")], {
                                                                     "callee": 0,
                                                                     "data.length": 0
                                                                 })
    bad += check(digest is not None and source_reason is None,
                 "the exact empty bytes source literal binds to certified length zero")
    return bad


def test_constructor_param_runtime_bytes_quote_mock_encodes_decode_payload():
    flat = """\
pragma solidity >=0.8.0;
interface IVault {
  function quoteArray(bytes calldata data) external returns (bytes memory);
  function quotePair(bytes calldata data) external returns (bytes memory);
}
contract Router {
  IVault private _vault;
  constructor(IVault vault) { _vault = vault; }
  function query(address pool, uint256 amount) external returns (uint256[] memory out) {
    return abi.decode(_vault.quoteArray(abi.encode(pool, amount)), (uint256[]));
  }
  function queryPair(address pool, uint256 amount) external returns (uint256 a, uint256 b) {
    return
      abi.decode(
        _vault.quotePair(abi.encode(pool, amount)),
        (uint256, uint256)
      );
  }
}
"""
    with tempfile.TemporaryDirectory() as project:
        os.makedirs(os.path.join(project, "src"))
        with open(os.path.join(project, "src", "flat.sol"), "w") as f:
            f.write(flat)
        specs = constructor_param_runtime_interface_mock_specs(project, "Router")
        pair_specs = constructor_param_runtime_interface_mock_specs(project, "Router", "queryPair")
    bad = 0
    bad += check(specs and specs[0].get("bytes_payload_returns") == ["uint256[]"],
                 f"quote bytes payload is recovered from abi.decode: {specs}")
    payloads = {tuple(spec.get("bytes_payload_returns") or []) for spec in specs}
    bad += check(("uint256", "uint256") in payloads,
                 f"tuple quote bytes payload is recovered from abi.decode: {specs}")
