def test_constructor_param_interface_calls_are_mocked_before_deploy():
    flat = """\
pragma solidity >=0.8.0;
interface IERC20 { function decimals() external view returns (uint8); }
interface IOracle { function getQuote(uint256 x) external view returns (uint256); }
interface IAuthority { function getImpl() external view returns (address); }
interface IRouter { function factory() external view returns (address); }
interface IFactory { function createPair(address a, address b) external returns (address); }
contract C {
  constructor(address token, address oracle, address authority, address router) {
    IERC20(token).decimals();
    require(IOracle(oracle).getQuote(1) != 0);
    setAuthority(authority);
    IRouter r = IRouter(router);
    IFactory(r.factory()).createPair(address(this), token);
  }
  function setAuthority(address authority) public {
    require((IAuthority(authority)).getImpl() != address(0));
  }
  function f() external {}
}
"""
    emitted = """\
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "./flat.sol";
contract CCovTest_0 is Test {
  C c0;
  function setUp() public {
    c0 = new C(address(uint160(1)), address(uint160(2)), address(uint160(3)), address(uint160(4)));
  }
  // claim: sol:@C@C@F@f#9:path:1
  function test_cov_0() public {
    c0.f();
  }
}
contract CCovTest_1 is Test {
  C c0;
  function setUp() public {
    c0 = new C(address(uint160(1)), address(uint160(2)), address(uint160(3)), address(uint160(4)));
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@C@F@f#9", 1)
    with tempfile.TemporaryDirectory() as project:
        os.makedirs(os.path.join(project, "src"))
        with open(os.path.join(project, "src", "flat.sol"), "w") as f:
            f.write(flat)
        specs = constructor_param_interface_mock_specs(project, "C")
    put = ["", "  function test_put_C_f_path1() public {", "    c0.f();", "  }"]
    text = assemble_put_source(em,
                               case, [put],
                               "CCovTest_0_put",
                               contract="C",
                               unit="f",
                               constructor_param_mocks=specs,
                               flat_source=flat)
    bad = 0
    new_at = text.find("c0 = new C(address(uint160(1)), "
                       "address(uint160(2)), address(uint160(3)), address(uint160(4)));")
    decimals_at = text.find('abi.encodeWithSignature("decimals()")')
    quote_at = text.find('abi.encodeWithSignature("getQuote(uint256)")')
    impl_at = text.find('abi.encodeWithSignature("getImpl()")')
    bad += check(len(specs) == 5, f"five constructor arg mocks found: {specs}")
    bad += check(0 <= decimals_at < new_at, "token decimals mock is inserted before deployment")
    bad += check(0 <= quote_at < new_at, "oracle quote mock is inserted before deployment")
    bad += check(0 <= impl_at < new_at, "indirect parenthesized interface mock is inserted before "
                 "deployment")
    bad += check("_ret_0 = address(uint160(3000))" in text,
                 "address return used by a constructor guard is nonzero")
    bad += check(
        "vm.mockCall(_esbmc_ctor_arg_mock_0_" in text
        and "_ret_0, abi.encodeWithSignature(\"createPair(address,address)\")" in text,
        "the chained factory call is mocked at factory()'s returned address")
    bad += check("address _esbmc_ctor_arg_mock" in text,
                 "constructor argument address is materialized for mockCall")
    bad += check("vm.etch(_esbmc_ctor_arg_mock_0_0," not in text,
                 "precompile constructor arguments are not etched")
    bad += check(
        text.count('abi.encodeWithSignature("decimals()")') == 2,
        "each test contract setUp gets its own constructor mocks")
    return bad


def test_constructor_return_alias_public_constant_getters_use_returned_address():
    flat = """\
pragma solidity >=0.8.0;
interface IProtocolFeeController {}
interface IVault {
  function getProtocolFeeController() external view returns (IProtocolFeeController);
}
contract ProtocolFeeController {
  uint256 public constant MAX_PROTOCOL_SWAP_FEE_PERCENTAGE = 50e16;
  uint256 public constant MAX_PROTOCOL_YIELD_FEE_PERCENTAGE = 50e16;
}
contract Provider {
  constructor(IVault vault) {
    IProtocolFeeController controller = vault.getProtocolFeeController();
    ProtocolFeeController(address(controller)).MAX_PROTOCOL_SWAP_FEE_PERCENTAGE();
    ProtocolFeeController(address(controller)).MAX_PROTOCOL_YIELD_FEE_PERCENTAGE();
  }
}
"""
    with tempfile.TemporaryDirectory() as project:
        os.makedirs(os.path.join(project, "src"))
        with open(os.path.join(project, "src", "flat.sol"), "w") as f:
            f.write(flat)
        specs = constructor_param_interface_mock_specs(project, "Provider")
    signatures = {spec["signature"]: spec for spec in specs}
    getter_sig = "getProtocolFeeController()"
    swap_sig = "MAX_PROTOCOL_SWAP_FEE_PERCENTAGE()"
    yield_sig = "MAX_PROTOCOL_YIELD_FEE_PERCENTAGE()"
    lines, changed = apply_constructor_param_interface_mocks([
        "  function setUp() public {", "    p = new Provider(IVault(address(uint160(7))));", "  }"
    ], "Provider", specs, flat)
    text = "\n".join(lines)
    returned_name = "_esbmc_ctor_arg_mock_0_0_ret_0"
    bad = 0
    bad += check(
        set(signatures) == {getter_sig, swap_sig, yield_sig},
        f"the getter and both public constants are source-grounded: {signatures}")
    bad += check(
        all(signatures[s].get("mock_address_from_signature") == getter_sig
            for s in (swap_sig, yield_sig)),
        f"both constant getters are tied to the vault getter return: {signatures}")
    bad += check(changed == 1, "one Provider deployment receives constructor mocks")
    bad += check(
        text.count(f"vm.mockCall({returned_name},") == 2,
        "both constant getters are mocked at the returned controller address")
    bad += check(
        text.rfind(f'vm.etch({returned_name}, hex"60006000f3");')
        > text.find("vm.clearMockedCalls();"),
        "the returned controller remains callable after constructor mock cleanup")
    bad += check(
        text.find(swap_sig) < text.find("p = new Provider(")
        and text.find(yield_sig) < text.find("p = new Provider("),
        "all controller mocks are installed before Provider deployment")
    return bad


