def test_constructor_struct_field_returned_runtime_interface_is_unit_scoped():
    flat = """\
pragma solidity >=0.8.0;
interface IHolder { function factory() external returns (address); }
interface IFactory { function create(address[] memory items) external returns (address); }
interface IAssetList { function getAssetInfo(uint256 i) external returns (uint256); }
interface IWrong { function getAssetInfo(uint256 i) external returns (uint256); }
contract Other {
  function unrelated(address assetList) external { IWrong(assetList).getAssetInfo(0); }
}
contract C {
  struct Config { address extensionDelegate; address[] assetConfigs; }
  address assetList;
  constructor(Config memory config) {
    address extensionDelegate = config.extensionDelegate;
    assetList = IFactory(IHolder(extensionDelegate).factory()).create(config.assetConfigs);
  }
  function getAssetInfo(uint256 i) external returns (uint256) {
    return IAssetList(assetList).getAssetInfo(i);
  }
  function getUtilization() external returns (uint256) {
    return 1;
  }
}
"""
    with tempfile.TemporaryDirectory() as project:
        os.makedirs(os.path.join(project, "src"))
        with open(os.path.join(project, "src", "flat.sol"), "w") as f:
            f.write(flat)
        scoped = constructor_param_struct_field_interface_mock_specs(project, "C", "getAssetInfo")
        unrelated = constructor_param_struct_field_interface_mock_specs(
            project, "C", "getUtilization")
    bad = 0
    bad += check(any(spec.get("returned_runtime_interface") == "IAssetList" for spec in scoped),
                 f"selected unit supplies the returned runtime interface: {scoped}")
    bad += check(
        unrelated and all(not spec.get("returned_runtime_interface") for spec in unrelated),
        f"other units do not inherit global same-name casts: {unrelated}")
    return bad


