def test_constructor_interface_return_binding_rejects_unsafe_comparisons():
    source_template = """\
pragma solidity >=0.8.0;
interface IVault {}
interface IController { function vault() external view returns (IVault); }
contract C {
  constructor(IVault first_, IVault second_, IController controller_) {
    %s
  }
}
"""
    spec = {
        "param_index": 2,
        "param_name": "controller_",
        "via_alias": "controller_",
        "signature": "vault()",
    }
    args = [
        "IVault(address(uint160(7)))", "IVault(address(uint160(9)))",
        "IController(address(uint160(8)))"
    ]
    unsafe = [
        "if (controller_.vault() == first_) revert();",
        "if (controller_.vault() != address(first_) + 1) revert();",
        "if (controller_.vault() != first_ && second_ == first_) revert();",
        "if (controller_.vault() != first_ || controller_.vault() != second_) revert();",
    ]
    bad = 0
    for statement in unsafe:
        tied = _constructor_interface_mock_return_expr(source_template % statement, "C", args, spec,
                                                       "IVault")
        bad += check(tied is None, f"unsafe constructor comparison is not bound: {statement}")
    decimals_template = """\
pragma solidity >=0.8.0;
interface IController { function decimals() external view returns (uint8); }
contract C {
  constructor(uint8 first_, uint8 second_, IController controller_) {
    %s
  }
}
"""
    decimals_spec = dict(spec, signature="decimals()")
    decimal_args = ["7", "9", "IController(address(uint160(8)))"]
    decimal_unsafe = [
        "if (controller_.decimals() == first_) revert();",
        "if (IController(controller_).decimals() == first_) revert();",
        "if (IController(address(controller_)).decimals() == first_) revert();",
        "if (controller_.decimals() != first_ + 1) revert();",
        "if (controller_.decimals() != first_ || controller_.decimals() != second_) revert();",
    ]
    for statement in decimal_unsafe:
        tied = _constructor_interface_mock_return_expr(decimals_template % statement, "C",
                                                       decimal_args, decimals_spec, "uint8")
        bad += check(tied is None, f"unsafe decimals comparison bypasses no binding: {statement}")
    return bad


