def test_constructor_struct_address_fields_with_code_guards_are_repaired():
    flat = """\
pragma solidity >=0.8.0;
library AddressUtils {
  error BadAddress();
  function checkContract(address addr) internal view returns (address) {
    if (addr.code.length == 0) revert BadAddress();
    return addr;
  }
}
abstract contract EVCClient {
  constructor(address evc) { AddressUtils.checkContract(evc); }
}
abstract contract Base is EVCClient {
  struct Integrations {
    address evc;
    address protocolConfig;
    address sequenceRegistry;
    address balanceTracker;
    address permit2;
  }
  constructor(Integrations memory integrations) EVCClient(integrations.evc) {
    AddressUtils.checkContract(integrations.protocolConfig);
    AddressUtils.checkContract(integrations.sequenceRegistry);
  }
}
abstract contract Dispatch is Base {
  struct DeployedModules {
    address initialize;
    address token;
    address optionalHook;
  }
  constructor(Integrations memory integrations, DeployedModules memory modules) Base(integrations) {
    MODULE_INITIALIZE = AddressUtils.checkContract(modules.initialize);
    MODULE_TOKEN = AddressUtils.checkContract(modules.token);
    optionalHook = modules.optionalHook;
  }
  address immutable MODULE_INITIALIZE;
  address immutable MODULE_TOKEN;
  address immutable optionalHook;
}
contract C is Dispatch {
  constructor(Integrations memory integrations, DeployedModules memory modules)
    Dispatch(integrations, modules)
  {}
  function f() external view returns (uint256) { return 1; }
}
"""
    emitted = """\
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {Base, C, Dispatch} from "./flat.sol";
contract Dep {}
contract CCovTest is Test {
  C c0;
  function setUp() public {
    Dep dep = new Dep();
    c0 = new C(
      Base.Integrations(address(0), address(dep), address(0), address(0), address(0)),
      Dispatch.DeployedModules(address(uint160(20)), address(uint160(21)), address(uint160(22)))
    );
  }
  // claim: sol:@C@C@F@f#9:path:1
  function test_cov_0() public {
    c0.f();
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as stream:
        stream.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@C@F@f#9", 1)
    with tempfile.TemporaryDirectory() as project:
        os.makedirs(os.path.join(project, "src"))
        with open(os.path.join(project, "src", "flat.sol"), "w") as stream:
            stream.write(flat)
        specs = constructor_param_hascode_specs(project, "C")
    put = ["", "  function test_put_C_f_path1() public {", "    c0.f();", "  }"]
    text = assemble_put_source(em,
                               case, [put],
                               "CCovTest_put",
                               contract="C",
                               unit="f",
                               constructor_param_hascode_mocks=specs,
                               flat_source=flat)
    fields = [(spec["param_index"], spec.get("field_name")) for spec in specs]
    bad = 0
    bad += check(
        set(fields) == {
            (0, "evc"),
            (0, "protocolConfig"),
            (0, "sequenceRegistry"),
            (1, "initialize"),
            (1, "token"),
        }, f"only mandatory code-checked struct fields are selected: {specs}")
    bad += check("Base.Integrations memory _esbmc_ctor_code_struct_0_0" in text,
                 "the integrations struct argument is copied into a mutable fixture")
    bad += check("Dispatch.DeployedModules memory _esbmc_ctor_code_struct_0_1" in text,
                 "the modules struct argument is copied into a mutable fixture")
    bad += check(
        "Base.Integrations(address(0), address(dep), address(0), address(0), address(0))" in text,
        "the copied struct preserves original field values")
    bad += check(
        "Dispatch.DeployedModules(address(uint160(20)), address(uint160(21)), address(uint160(22)))"
        in text, "the copied modules struct preserves original field values")
    for param_idx, field in fields:
        fixture = f"_esbmc_ctor_code_struct_0_{param_idx}"
        bad += check(f"address _esbmc_ctor_code_" in text and f"= {fixture}.{field};" in text,
                     f"the {field} field is etched in place")
        bad += check(f"{fixture}.{field} =" not in text,
                     f"the {field} field value is not rewritten")
    bad += check("_esbmc_ctor_code_struct_0_0.balanceTracker =" not in text,
                 "an unchecked address field is not rewritten")
    bad += check("_esbmc_ctor_code_struct_0_1.optionalHook =" not in text,
                 "an unchecked module field is not rewritten")
    bad += check(
        text.count("vm.etch(_esbmc_ctor_code_") == 5, "each mandatory contract field receives code")
    bad += check(
        text.count(".code.length == 0") >= 5,
        "existing dependency code is preserved instead of overwritten")
    deploy_at = text.find("new C(")
    bad += check(
        deploy_at >= 0 and "_esbmc_ctor_code_struct_0_0" in text[deploy_at:]
        and "_esbmc_ctor_code_struct_0_1" in text[deploy_at:],
        "deployment uses the repaired struct fixtures")
    return bad


