def test_inherited_constructor_param_iscontract_arg_is_etched_before_deploy():
    emitted = """\
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "./flat.sol";
contract CCovTest_0 is Test {
  C c0;
  function setUp() public {
    c0 = new C(address(uint160(0)), address(uint160(1)));
  }
  // claim: sol:@C@C@F@f#9:path:1
  function test_cov_0() public {
    c0.f();
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@C@F@f#9", 1)
    with tempfile.TemporaryDirectory() as project:
        os.makedirs(os.path.join(project, "src"))
        with open(os.path.join(project, "src", "flat.sol"), "w") as f:
            f.write(INHERITED_HASCODE_CTOR_FLAT)
        specs = constructor_param_hascode_specs(project, "C")
    put = ["", "  function test_put_C_f_path1() public {", "    c0.f();", "  }"]
    text = assemble_put_source(em,
                               case, [put],
                               "CCovTest_0_put",
                               contract="C",
                               unit="f",
                               constructor_param_hascode_mocks=specs,
                               flat_source=INHERITED_HASCODE_CTOR_FLAT)
    new_at = text.find("c0 = new C(address(uint160(0)), address(uint160(1)));")
    impl_at = text.find("address _esbmc_ctor_code_0_0 = address(uint160(0));")
    owner_at = text.find("address _esbmc_ctor_code_0_1 = address(uint160(1));")
    bad = 0
    bad += check(specs == [{
        "param_index": 0,
        "param_name": "impl"
    }], f"only the inherited isContract implementation arg is found: {specs}")
    bad += check(0 <= impl_at < new_at,
                 "the inherited isContract constructor arg is etched before deploy")
    bad += check(owner_at < 0, "unrelated address constructor args are not etched")
    return bad


