def test_constructor_nonzero_rejects_non_mandatory_comparisons_and_helpers():
    comparison_only = """\
pragma solidity >=0.8.0;
contract C {
  constructor(address owner) {
    bool ok = owner != address(0);
    ok;
  }
}
"""
    conditional_base = """\
pragma solidity >=0.8.0;
abstract contract Base {
  constructor(address owner, bool enforce) {
    if (enforce) {
      require(owner != address(0));
    }
  }
}
contract C is Base {
  constructor(address owner) Base(owner, false) {}
}
"""
    conditional_helper = """\
pragma solidity >=0.8.0;
contract C {
  constructor(address owner, bool enforce) {
    if (enforce) validate(owner);
  }
  function validate(address candidate) internal view {
    require(candidate != address(0));
  }
}
"""
    modified_helper = """\
pragma solidity >=0.8.0;
contract C {
  modifier gate() { _; }
  constructor(address owner) {
    validate(owner);
  }
  function validate(address candidate) internal view gate {
    require(candidate != address(0));
  }
}
"""
    conditional_mint = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_, bool enforce) {
    owner = owner_;
    if (enforce) setup();
    if (enforce) onlyOwner();
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function _mint(address, uint256) internal {}
  function onlyOwner() internal view {
    require(msg.sender == owner);
  }
}
"""
    constructor_modifier = """\
pragma solidity >=0.8.0;
contract C {
  modifier maybe(address owner) {
    if (owner != address(0)) _;
  }
  constructor(address owner) maybe(owner) {
    require(owner != address(0));
  }
}
"""
    skip_modifier_sender = """\
pragma solidity >=0.8.0;
contract C {
  bool _skip;
  address public owner;
  modifier skip() {
    _skip = true;
  }
  constructor(address owner_) {
    owner = owner_;
    setup();
    onlyOwner();
  }
  function setup() internal skip {
    _mint(msg.sender, 1);
  }
  function onlyOwner() internal view {
    require(msg.sender == owner);
  }
  function _mint(address, uint256) internal {}
}
"""
    comparison_sender_guard = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_) {
    owner = owner_;
    setup();
    check();
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function check() internal view {
    bool ok = msg.sender == owner;
    ok;
  }
  function _mint(address, uint256) internal {}
}
"""
    conditional_sender_guard = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_) {
    owner = owner_;
    setup();
    check(false);
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function check(bool enforce) internal view {
    if (enforce) require(msg.sender == owner);
  }
  function _mint(address, uint256) internal {}
}
"""
    sender_guard_formal_shadow = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_) {
    owner = owner_;
    setup();
    check(msg.sender);
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function check(address owner) internal view {
    require(msg.sender == owner);
  }
  function _mint(address, uint256) internal {}
}
"""
    sender_guard_local_shadow = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_) {
    owner = owner_;
    setup();
    check();
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function check() internal view {
    address owner = msg.sender;
    require(msg.sender == owner);
  }
  function _mint(address, uint256) internal {}
}
"""
    sender_guard_modifier_shadow = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  modifier onlyAdmin(address owner) {
    require(msg.sender == owner);
    _;
  }
  constructor(address owner_) {
    owner = owner_;
    setup();
    check();
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function check() internal view onlyAdmin(msg.sender) {}
  function _mint(address, uint256) internal {}
}
"""
    sender_guard_tuple_local_shadow = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_) {
    owner = owner_;
    setup();
    check();
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function pair() internal view returns (address, uint256) {
    return (msg.sender, 0);
  }
  function check() internal view {
    (address owner,) = pair();
    require(msg.sender == owner);
  }
  function _mint(address, uint256) internal {}
}
"""
    sender_guard_named_return_shadow = """\
pragma solidity >=0.8.0;
contract C {
  address public owner;
  constructor(address owner_) {
    owner = owner_;
    setup();
    check();
  }
  function setup() internal {
    _mint(msg.sender, 1);
  }
  function check() internal view returns (address owner) {
    owner = msg.sender;
    require(msg.sender == owner);
  }
  function _mint(address, uint256) internal {}
}
"""
    bad = 0
    bad += check(
        constructor_param_nonzero_specs(comparison_only, "C") == [],
        "a non-reverting comparison is not a nonzero constructor guard")
    bad += check(
        constructor_param_nonzero_specs(conditional_base, "C") == [],
        "a conditional inherited nonzero guard does not rewrite zero")
    bad += check(
        constructor_param_nonzero_specs(conditional_helper, "C") == [],
        "a conditionally called helper guard does not rewrite zero")
    bad += check(
        constructor_param_nonzero_specs(modified_helper, "C") == [],
        "a helper with a modifier is not treated as a mandatory guard")
    bad += check(
        constructor_param_nonzero_specs(conditional_mint, "C") == [],
        "conditional sender mint/state guard does not rewrite zero")
    bad += check(
        constructor_param_nonzero_specs(constructor_modifier, "C") == [],
        "constructor modifiers disable nonzero argument repair")
    bad += check(
        constructor_param_nonzero_specs(skip_modifier_sender, "C") == [],
        "modifier identifiers containing underscores do not fake `_` execution")
    bad += check(
        constructor_param_nonzero_specs(comparison_sender_guard, "C") == [],
        "plain sender equality is not a mandatory sender-state guard")
    bad += check(
        constructor_param_nonzero_specs(conditional_sender_guard, "C") == [],
        "conditional sender equality is not a mandatory sender-state guard")
    bad += check(
        constructor_param_nonzero_specs(sender_guard_formal_shadow, "C") == [],
        "function formals do not shadow-match state sender guards")
    bad += check(
        constructor_param_nonzero_specs(sender_guard_local_shadow, "C") == [],
        "function locals do not shadow-match state sender guards")
    bad += check(
        constructor_param_nonzero_specs(sender_guard_modifier_shadow, "C") == [],
        "modifier formals do not shadow-match state sender guards")
    bad += check(
        constructor_param_nonzero_specs(sender_guard_tuple_local_shadow, "C") == [],
        "tuple local declarations do not shadow-match state sender guards")
    bad += check(
        constructor_param_nonzero_specs(sender_guard_named_return_shadow, "C") == [],
        "named return parameters do not shadow-match state sender guards")
    return bad


def test_constructor_strict_order_guard_repairs_defaults_and_clock():
    flat = """\
pragma solidity >=0.8.0;
contract C {
  constructor(uint256 minAge, uint256 maxAge) {
    if (maxAge <= minAge) revert("low");
    if (maxAge > block.timestamp) revert("future");
  }
  function valid(string calldata label) external pure returns (bool) {
    return bytes(label).length >= 3;
  }
}
"""
    emitted = """\
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "./flat.sol";
contract CCovTest is Test {
  C c0;
  function setUp() public {
    c0 = new C(uint256(0), uint256(0));
  }
  // claim: sol:@C@C@F@valid#9:path:1
  function test_cov_0() public {
    c0.valid("abc");
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@C@F@valid#9", 1)
    text = assemble_put_source(
        em,
        case, [[
            "", "  function test_put_C_valid_path1(string memory label) public {",
            "    c0.valid(label);", "  }"
        ]],
        "CCovTest_put",
        contract="C",
        unit="valid",
        flat_source=flat)
    bad = 0
    forward_warp = "if (block.timestamp < 1) vm.warp(1);"
    bad += check(forward_warp in text,
                 "constructor clock advances only when the source cap requires it")
    bad += check(
        text.index(forward_warp) < text.index("new C(uint256(0), uint256(1))") <
        text.index("function test_put_C_valid_path1"),
        "the constructor clock is established before deployment")
    bad += check("__veriputCtorTimestamp" not in text,
                 "the replay never warps backwards after deployment")
    bad += check("new C(uint256(0), uint256(1))" in text,
                 "equal defaults are repaired to the source-required strict order")
    bad += check("new C(uint256(0), uint256(0))" not in text,
                 "the source-rejected equal constructor defaults are gone")
    return bad


def test_constructor_strict_order_skips_conditional_and_modifier_guards():
    conditional = """\
pragma solidity >=0.8.0;
contract C {
  constructor(bool enforce, uint256 low, uint256 high) {
    if (enforce) {
      if (high <= low) revert("conditional");
    }
  }
}
"""
    modified = """\
pragma solidity >=0.8.0;
contract C {
  modifier gated() { _; }
  constructor(uint256 low, uint256 high) gated {
    if (high <= low) revert("modified");
  }
}
"""
    bad = 0
    bad += check(
        constructor_param_strict_order_specs(conditional, "C") == [],
        "a nested conditional revert is not treated as a deployment invariant")
    bad += check(
        constructor_param_strict_order_specs(modified, "C") == [],
        "a constructor modifier makes strict-order inference conservative")
    lines = ["    c0 = new C(false, uint256(0), uint256(0));"]
    repaired, changed = apply_constructor_param_strict_orders(lines, "C", [])
    bad += check(changed == 0 and repaired == lines,
                 "a source-valid conditional fixture remains byte-for-byte unchanged")
    return bad


def test_constructor_clock_repair_refuses_timestamp_sensitive_target():
    flat = """\
pragma solidity >=0.8.0;
contract C {
  uint256 public createdAt;
  constructor(uint256 low, uint256 high) {
    if (high <= low) revert("low");
    if (high > block.timestamp) revert("future");
    createdAt = block.timestamp;
  }
  function elapsed() external view returns (uint256) {
    return block.timestamp - createdAt;
  }
}
"""
    stateful_without_clock = """\
pragma solidity >=0.8.0;
contract C {
  uint256 public threshold;
  constructor(uint256 low, uint256 high) {
    if (high <= low) revert("low");
    threshold = high;
  }
  function branch() external view returns (bool) {
    return threshold == 1;
  }
}
"""
    fake_pure_comment = flat.replace("function elapsed() external view",
                                     "function elapsed() external /* pure */ view")
    fake_pure_declaration = """\
pragma solidity >=0.8.0;
contract Base {
  uint256 internal createdAt;
  function elapsed() external view returns (uint256) {
    return block.timestamp - createdAt;
  }
}
contract C is Base {
  string internal constant note = "function elapsed() external pure {}";
  /* function elapsed() external pure returns (uint256) { return 0; } */
  constructor(uint256 low, uint256 high) {
    if (high <= low) revert("low");
    createdAt = block.timestamp;
  }
}
"""
    specs = constructor_param_strict_order_specs(flat, "C", "elapsed")
    lines = ["    c0 = new C(uint256(100), uint256(100));"]
    repaired, changed = apply_constructor_param_strict_orders(lines, "C", specs)
    bad = 0
    bad += check(specs == [], "timestamp-sensitive targets require a certified constructor fixture")
    bad += check(changed == 0 and repaired == lines,
                 "an impossible pre-deployment target timestamp is not synthesized")
    bad += check(not any("vm.warp" in line for line in repaired),
                 "the refused repair cannot introduce backward or unauthenticated time")
    bad += check(
        constructor_param_strict_order_specs(stateful_without_clock, "C", "branch") == [],
        "state-sensitive targets cannot adopt constructor parameter rewrites")
    bad += check(
        constructor_param_strict_order_specs(fake_pure_comment, "C", "elapsed") == [],
        "a pure token inside a comment cannot bypass the mutability gate")
    bad += check(
        constructor_param_strict_order_specs(fake_pure_declaration, "C", "elapsed") == [],
        "commented and stringified pure declarations are not executable metadata")
    return bad


