def _immutable_return_put(constructor_arg):
    source = """
contract BobVaultShare {
  uint8 internal immutable _DECIMALS;
  constructor(uint8 decimals_) { _DECIMALS = decimals_; }
  function decimals() public view returns (uint8) { return _DECIMALS; }
}
"""
    emitted_text = f"""\
pragma solidity >=0.8.0;
contract BobVaultShareCovTest is Test {{
  BobVaultShare c0;
  function setUp() public {{ c0 = new BobVaultShare({constructor_arg}); }}
  // claim: sol:@C@BobVaultShare@F@decimals#1:path:3
  function test_cov_0() public {{
    vm.prank(address(uint160(1)));
    c0.decimals();
  }}
}}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as out:
        out.write(emitted_text)
    try:
        emitted = EmittedFile(path)
    finally:
        os.unlink(path)
    case = emitted.case_for("sol:@C@BobVaultShare@F@decimals#1", 3)
    notes = []
    put, stats = build_put(
        "BobVaultShare",
        "decimals",
        3,
        1,
        "sol:@C@BobVaultShare@F@decimals#1",
        {"msg.sender": (1, (1 << 160) - 1)},
        {},
        {"state._DECIMALS": 0},
        [],
        emitted,
        case,
        {},
        [("return", RETLIVE, "REFUTED"), ("return", "return == state._DECIMALS", "HOLDS")],
        notes,
        rettypes=[("", "uint8")],
        r2_terms={
            "state._DECIMALS": {
                "kind": "coord",
                "name": "state._DECIMALS",
            },
        },
        exit_kind="normal",
        flat_source=source,
    )
    return "\n".join(put or []), stats, notes


