    put = ["", "  function test_put_C_f_path1() public {", "    c0.f();", "  }"]
    text = assemble_put_source(em,
                               case, [put],
                               "CCovTest_put",
                               contract="C",
                               unit="f",
                               flat_source=flat)
    bad = 0
    bad += check("VeriPUT completed inherited/overloaded interface stubs" in text,
                 "the mock completion note is emitted")
    bad += check(
        "function safeTransferFrom(address, address, uint256) "
        "external pure override {}" in text, "the inherited overload is added to the ESBMC mock")
    bad += check(
        "function safeTransferFrom(address, address, uint256, "
        "bytes memory) external pure override {}" in text, "the existing overload is preserved")
    bad += check(
        "function latestRoundData() external pure override returns "
        "(uint80, int256, uint256, uint256, uint80) "
        "{ return (uint80(1), int256(0), uint256(1), uint256(1), "
        "uint80(1)); }" in text, "the malformed tuple-return mock is repaired")
    return bad


