def test_nonpayable_abi_reject_replay_is_synthesized_from_high_level_call():
    body, call_i, established, sig, pre, note = establish_env_value(
        ["    try c0.f(address(uint160(7))) {} catch {}"],
        0, {"msg.value": (1, (1 << 256) - 1)}, {}, {},
        "p_msg_value",
        sender_expr="address(this)",
        unit="f",
        nonpayable_abi_signature="f(address)")
    text = "\n".join(body)
    bad = 0
    bad += check(established == "msg.value" and sig == ("uint256", "p_msg_value"),
                 "the certified nonzero value coordinate becomes a fuzz input")
    bad += check(
        'address(c0).call{value: p_msg_value}(abi.encodeWithSignature("f(address)", '
        'address(uint160(7))))' in text,
        "the nonpayable high-level replay becomes an ABI-compatible low-level call")
    bad += check("assertFalse(_esbmc_value_gate_ok" in text,
                 "the compiler ABI rejection remains an executable R0 oracle")
    bad += check(call_i == 0 and pre and "bound(p_msg_value, 1," in pre[0],
                 f"the target index and nonzero full-domain bound are retained: {pre}")
    bad += check("compiler-only nonpayable reject replay" in (note or ""),
                 "the structural rewrite is disclosed")
    return bad


