def test_extra_numeric_env_ranges_use_modeled_cheatcodes():
    """Modeled uint256 env setters become bounded PUT fuzz parameters."""
    em, case = make_case()
    notes = []
    put, stats = build_put("FeeVault",
                           "setDiscount",
                           7,
                           2,
                           "sol:@C@FeeVault@F@setDiscount#61",
                           region={
                               "bps": (0, 250),
                               "u": (0, (1 << 160) - 1),
                               "block.basefee": (1, 3),
                               "block.difficulty": (4, 6),
                               "block.prevrandao": (4, 6),
                               "tx.gasprice": (7, 9)
                           },
                           holes={"block.prevrandao": [5]},
                           pins={},
                           params=PARAMS,
                           emitted=em,
                           case=case,
                           layout=LAYOUT,
                           ladder_rows=[
                               ("byFee[block.basefee]", "post == pre", "HOLDS"),
                               ("byRand[block.prevrandao]", "post == pre", "HOLDS"),
                               ("byGas[tx.gasprice]", "post == pre", "HOLDS"),
                           ],
                           notes=notes,
                           maps={
                               "byFee": (7, "uint256", 32, 0, "byFee", None),
                               "byRand": (8, "uint256", 32, 0, "byRand", None),
                               "byGas": (9, "uint256", 32, 0, "byGas", None)
                           })
    text = "\n".join(put or [])
    bad = 0
    bad += check(put is not None, f"modeled numeric env ranges emit: {notes}")
    bad += check(
        "uint256 p_block_basefee" in text
        and "p_block_basefee = bound(p_block_basefee, 1, 3);" in text
        and "    vm.fee(p_block_basefee);" in text, "block.basefee is established by vm.fee")
    bad += check(
        "uint256 p_block_prevrandao" in text
        and "p_block_prevrandao = bound(p_block_prevrandao, 4, 6);" in text
        and "vm.assume(p_block_prevrandao != 5);" in text
        and "    vm.prevrandao(uint256(p_block_prevrandao));" in text,
        "block.prevrandao is established with holes")
    bad += check("p_block_difficulty" not in text
                 and text.count("vm.prevrandao(") == 1,
                 "block.difficulty shares the single prevrandao cheatcode")
    bad += check(
        "uint256 p_tx_gasprice" in text and "p_tx_gasprice = bound(p_tx_gasprice, 7, 9);" in text
        and "    vm.txGasPrice(p_tx_gasprice);" in text,
        "tx.gasprice is established by vm.txGasPrice")
    bad += check(
        stats["fuzz_params"] == 5
        and {"block.basefee", "block.prevrandao", "tx.gasprice"} <= set(stats["lifted"]),
        f"numeric env ranges are counted as fuzzed: {stats}")
    bad += check(
        "keccak256(abi.encode(p_block_basefee, uint256(7)))" in text
        and "keccak256(abi.encode(p_block_prevrandao, uint256(8)))" in text
        and "keccak256(abi.encode(p_tx_gasprice, uint256(9)))" in text,
        "modeled numeric env coordinates key storage oracles")
    return bad


