def test_certified_ce_binder_matches_store_alias_and_symbolic_key():
    """`state._rOwned$952[msg.sender]` (CE, msg.sender=0) is the witness's
    `state._rOwned[0]` (ANCHToken, full-20260822-v40 round 9)."""
    claim = {"inputs": {}, "env": {"msg.sender": "0", "msg.value": "0"},
             "entry_storage": {"_rOwned[0]": "5", "_decimals": "9"}}
    expected = {"msg.sender": "0", "msg.value": "0",
                "state._rOwned$952[msg.sender]": "5", "state._decimals": "9"}
    binding, reason = bind_emitted_claim_to_certified_ce(claim, expected)
    bad = check(reason is None and binding["status"] == "exact",
                f"alias + symbolic key binds exactly: {binding}, {reason}")
    other = dict(expected); other["state._rOwned$952[msg.sender]"] = "6"
    binding, reason = bind_emitted_claim_to_certified_ce(claim, other)
    bad += check(binding is None and "different=" in reason,
                 f"a different value is still refused: {reason}")
    bad += check(store_alias_variants("_rOwned$952") == ["_rOwned$952", "_rOwned"]
                 and store_alias_variants("wards") == ["wards"],
                 "alias variants: suffix stripped once, plain name unchanged")
    return bad


def test_certified_basis_requires_the_exact_certified_ce():
    claim = {
        "inputs": {
            "amount": "0x07"
        },
        "env": {
            "msg.sender": "9",
            "msg.value": "0"
        },
        "entry_storage": {
            "balance": "11"
        },
    }
    expected = {
        "amount": "7",
        "msg.sender": "9",
        "msg.value": "0",
        "state.balance": "11",
        "return": "3",
    }
    binding, reason = bind_emitted_claim_to_certified_ce(claim, expected)
    bad = check(reason is None and binding["status"] == "exact",
                f"equal CE coordinates bind exactly: {binding}, {reason}")
    changed = dict(expected, amount="8")
    binding, reason = bind_emitted_claim_to_certified_ce(claim, changed)
    bad += check(binding is None and "different=amount" in reason,
                 f"same-path different input is refused: {reason}")
    malformed = dict(expected, amount={"not": "scalar"})
    binding, reason = bind_emitted_claim_to_certified_ce(claim, malformed)
    bad += check(binding is None and "non-scalar" in reason,
                 f"unrenderable CE is refused: {reason}")
    body = [
        "    vm.prank(address(uint160(9)));",
        "    c0.f(uint256(7));",
    ]
    source_sha, reason = bind_emitted_source_to_certified_ce(body, 1, "f", [("amount", "uint256")],
                                                             {
                                                                 "amount": "7",
                                                                 "msg.sender": "9",
                                                             })
    bad += check(source_sha is not None and reason is None,
                 f"rendered scalar call is bound to its CE: {reason}")
    source_sha, reason = bind_emitted_source_to_certified_ce([body[0], "    c0.f(uint256(8));"], 1,
                                                             "f", [("amount", "uint256")], {
                                                                 "amount": "7",
                                                                 "msg.sender": "9",
                                                             })
    bad += check(source_sha is None and "differs" in reason,
                 f"rendered call with another input is refused: {reason}")
    source_sha, reason = bind_emitted_source_to_certified_ce(body, 1, "f", [("amount", "uint256"),
                                                                            ("omitted", "uint256")],
                                                             {
                                                                 "amount": "7",
                                                                 "msg.sender": "9",
                                                             })
    bad += check(source_sha is None and "arguments do not match" in reason,
                 f"defaulted or missing argument is refused: {reason}")
    dyn_body = [body[0], '    c0.g("abc", uint256(7));']
    dyn_params = [("description", "string calldata"), ("amount", "uint256")]
    dyn_audit = {}
    source_sha, reason = bind_emitted_source_to_certified_ce(
        dyn_body, 1, "g", dyn_params, {"amount": "7", "msg.sender": "9"}, audit=dyn_audit)
    bad += check(source_sha is not None and reason is None,
                 f"a string argument the CE never mentions binds (unread on the path): {reason}")
    bad += check((dyn_audit.get("coordinates") or dyn_audit.get("bindings") or {}).get(
        "description", {}).get("kind") == "ce-unconstrained-dynamic-call-argument"
                 or "ce-unconstrained-dynamic-call-argument" in json.dumps(dyn_audit),
                 "the unconstrained dynamic argument is recorded in the audit")
    source_sha, reason = bind_emitted_source_to_certified_ce(
        dyn_body, 1, "g", dyn_params, {"amount": "7", "msg.sender": "9",
                                       "description.length": "3"})
    bad += check(source_sha is None and "no exact certified CE coordinate" in (reason or ""),
                 f"a string the CE constrains by length is still refused: {reason}")
    gate_body = [
        "    vm.deal(address(uint160(1)), 1);",
        "    vm.prank(address(uint160(1)));",
        "    (bool ok, ) = address(c0).call{value: 1}(",
        '        abi.encodeWithSignature("f()"));',
        "    assertFalse(ok);",
    ]
    gate_ce = {
        "msg.data": "0",
        "msg.sender": "0",
        "msg.sig": "0",
        "msg.value": "1",
        "state.feed": "7",
    }
    projection = abi_value_gate_ce_projection(gate_ce, [], stage4_kind="abi-value-gate")
    audit = {}
    source_sha, reason = bind_emitted_source_to_certified_ce(gate_body,
                                                             find_unit_call(gate_body, "f"),
                                                             "f", [],
                                                             gate_ce,
                                                             coordinate_evidence=projection,
                                                             audit=audit)
    bad += check(source_sha is not None and reason is None,
                 f"the structural ABI gate binds the complete CE: {reason}")
    bad += check(
        audit.get("ce_sha256") == source_sha
        and audit.get("coordinates", {}).get("msg.sender", {}).get("rendered") == 1
        and audit.get("coordinates", {}).get("state.feed", {}).get("certified") == 7,
        f"the audit records rendered and projected full-CE coordinates: {audit}")
    wrong_value = list(gate_body)
    wrong_value[2] = wrong_value[2].replace("value: 1", "value: 2")
    source_sha, reason = bind_emitted_source_to_certified_ce(wrong_value,
                                                             find_unit_call(wrong_value, "f"),
                                                             "f", [],
                                                             gate_ce,
                                                             coordinate_evidence=projection)
    bad += check(source_sha is None and "msg.value" in reason,
                 "the ABI projection never permits a different msg.value")
    return bad


def test_extcall_fixture_projection_is_structural_and_region_bounded():
    source = """\
contract Proxy {
  function forward(address callee, bytes memory data) public {
    { (bool success,) = callee.call(data); require(success); }
  }
}
"""
    expected = {
        "callee": "0",
        "data.length": "0",
        "msg.sender": "0",
        "msg.value": "0",
        "state.owner": "0",
    }
    region = {
        "callee": ["0", str((1 << 160) - 1)],
        "data.length": ["0", str((1 << 64) - 1)],
    }
    params = [("callee", "address"), ("data", "bytes memory")]
    projection = extcall_fixture_ce_projection(source, "Proxy", "forward", expected, params, region,
                                               {"extcall.success": "1"})
    body = [
        "    vm.prank(address(uint160(7)));",
        "    vm.mockCall(address(uint160(13125)), hex\"\", bytes(\"\"));",
        "    c0.forward(address(uint160(13125)), hex\"\");",
    ]
    audit = {}
    digest, reason = bind_emitted_source_to_certified_ce(body,
                                                         2,
                                                         "forward",
                                                         params,
                                                         expected,
                                                         coordinate_evidence=projection,
                                                         audit=audit)
    bad = check(digest is not None and reason is None,
                f"strict extcall fixture projects an executable region member: {reason}")
    callee = audit.get("coordinates", {}).get("callee", {})
    bad += check(
        callee.get("rendered") == 13125 and callee.get("lo") == 0
        and callee.get("hi") == (1 << 160) - 1,
        f"extcall projection audit retains certified region bounds: {callee}")
    digest, reason = bind_emitted_source_to_certified_ce([body[0], body[2]],
                                                         1,
                                                         "forward",
                                                         params,
                                                         expected,
                                                         coordinate_evidence=projection)
    bad += check(digest is None and "exact callsite mock" in reason,
                 f"a projected replay without its extcall mock is refused: {reason}")
    cleared = [body[0], body[1], "    vm.clearMockedCalls();", body[2]]
    digest, reason = bind_emitted_source_to_certified_ce(cleared,
                                                         3,
                                                         "forward",
                                                         params,
                                                         expected,
                                                         coordinate_evidence=projection)
    bad += check(digest is None and "exact callsite mock" in reason,
                 f"a cleared extcall mock cannot authenticate the call: {reason}")
    conditional = [body[0], "    if (false) {", "      " + body[1].strip(), "    }", body[2]]
    digest, reason = bind_emitted_source_to_certified_ce(conditional,
                                                         4,
                                                         "forward",
                                                         params,
                                                         expected,
                                                         coordinate_evidence=projection)
    bad += check(digest is None and "exact callsite mock" in reason,
                 f"a conditional extcall mock cannot authenticate the call: {reason}")
    outside = list(body)
    outside[1] = "    vm.mockCall(address(uint160(9)), hex\"\", bytes(\"\"));"
    outside[2] = "    c0.forward(address(uint160(9)), hex\"\");"
    narrow = extcall_fixture_ce_projection(source, "Proxy", "forward", expected, params, {
        "callee": ["0", "8"],
        "data.length": ["0", "0"]
    }, {"extcall.success": "1"})
    digest, reason = bind_emitted_source_to_certified_ce(outside,
                                                         2,
                                                         "forward",
                                                         params,
                                                         expected,
                                                         coordinate_evidence=narrow)
    bad += check(digest is None and "callee" in reason and "region" in reason,
                 f"an address outside the certified region is refused: {reason}")
    reads_sender = source.replace("{ (bool success,)",
                                  "require(msg.sender != address(0)); { (bool success,)")
    bad += check(
        extcall_fixture_ce_projection(reads_sender, "Proxy", "forward", expected, params, region,
                                      {"extcall.success": "1"}) is None,
        "an extra sender-dependent statement cannot acquire the certificate")
    bad += check(
        extcall_fixture_ce_projection(source, "Proxy", "forward", expected, params, region,
                                      {"extcall.other": "1"}) is None,
        "a pin not naming the exact low-level-call result is refused")
    return bad


def test_synthetic_claim_retains_report_ce_coordinates():
    path_function = "sol:@C@Feed@F@latest#201"
