def test_a_bool_return_can_assert_a_structured_bool_coord():
    from solidity_path_put import return_rung_assertions  # noqa: E402

    coord = return_rung_assertions("return == ok", ("bool", None), "_put_ret",
                                   "return: return == ok", {"ok": "p_ok"},
                                   {"ok": {
                                       "kind": "coord",
                                       "name": "ok"
                                   }})
    literal = return_rung_assertions("return == 1", ("bool", None), "_put_ret",
                                     "return: return == 1", {}, {})
    bad_literal = return_rung_assertions("return == 2", ("bool", None), "_put_ret",
                                         "return: return == 2", {}, {})
    neq_zero = return_rung_assertions("return != 0", ("bool", None), "_put_ret",
                                      "return: return != 0", {}, {})
    neq_one = return_rung_assertions("return != 1", ("bool", None), "_put_ret",
                                     "return: return != 1", {}, {})
    bad_neq = return_rung_assertions("return != 2", ("bool", None), "_put_ret",
                                     "return: return != 2", {}, {})
    bad = 0
    bad += check(coord == ['    assertEq(_put_ret, p_ok, "return: return == ok");'],
                 f"a bool return can compare against a certified bool coord: {coord}")
    bad += check(literal == ['    assertTrue(_put_ret, "return: return == 1");'],
                 f"a numeric bool literal is rendered as bool without R2 terms: {literal}")
    bad += check(bad_literal is None, f"out-of-domain bool literal is still refused: {bad_literal}")
    bad += check(neq_zero == ['    assertTrue(_put_ret, "return: return != 0");'],
                 f"bool return != 0 is assertTrue: {neq_zero}")
    bad += check(neq_one == ['    assertFalse(_put_ret, "return: return != 1");'],
                 f"bool return != 1 is assertFalse: {neq_one}")
    bad += check(bad_neq is None, f"out-of-domain bool inequality is still refused: {bad_neq}")
    return bad


