def test_contract_state_store_aliases_read_solc_declaration_ids():
    from solidity_ast_dependencies import contract_state_esbmc_store_names  # noqa: E402

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "Base",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [
                {
                    "nodeType": "VariableDeclaration",
                    "id": 10,
                    "name": "owner",
                    "stateVariable": True
                },
            ]
        }, {
            "nodeType":
            "ContractDefinition",
            "name":
            "Token",
            "id":
            2,
            "linearizedBaseContracts": [2, 1],
            "nodes": [
                {
                    "nodeType": "VariableDeclaration",
                    "id": 496,
                    "name": "_allowances",
                    "stateVariable": True
                },
            ]
        }]
    }
    fd, path = tempfile.mkstemp(suffix=".solast")
