def test_assert_query_keeps_state_pins_for_the_certified_slice():
    """State pins are single-point entry assumptions for --path-cov-assert.

    A wide state region is still not passed through this helper.  A scalar
    storage pin can be queried, but a source-level constant or immutable that
    has no solc storage slot cannot be resolved by ESBMC's assertion ladder and
    must not poison the whole query.
    """
    keep, skipped = assert_query_pins({
        "state._DOCKED": 255,
        "state.owner": 7,
        "msg.value": 0
    },
                                      layout={"owner": (0, 0, 20)},
                                      maps={})
    bad = 0
    bad += check(keep == {
        "msg.value": 0,
        "state.owner": 7
    }, f"only ladder-resolvable state pins remain in the assert spec: {keep}")
    bad += check(
        len(skipped) == 1 and "state._DOCKED" in skipped[0]
        and "no solc storage slot" in skipped[0],
        f"source-level constant/immutable pin is skipped: {skipped}")
    return bad


