    entries, entry_skipped = assert_query_region_entries(region, {}, layout, maps, params)
    entry_names = [entry["name"] for entry in entries]
    query_pins, pin_skipped = assert_query_pins({name: 0 for name in region}, layout, maps, params)
    bad += check(
        entry_names == ["state.balances[state.cfg.owner]", "state.balances[who]"]
        and sorted(query_pins) == entry_names,
        f"region and pin query paths use the same key policy: entries={entry_names}, "
        f"pins={sorted(query_pins)}")
    bad += check(
        any("state.does.not.exist" in item for item in entry_skipped)
        and any("state.does.not.exist" in item for item in pin_skipped),
        f"unknown nested state keys are explicit skips: region={entry_skipped}, "
        f"pins={pin_skipped}")
    return bad


