def test_r2_refutation_observation_is_scoped_to_exact_failed_claim():
    log = """\
✗ FAILED: 'C:f:path:3#r2_boundary_y at file flat.sol line 7 function f'
--path-cov-assert: y: post in [5, 50]  REFUTED
✗ FAILED: 'C:f:path:3#r2_boundary_return at'
--path-cov-assert: return: return in [1, 9]  REFUTED
"""
    report = {
        "claims": [{
            "condition": "C:f:path:3#r2_boundary_y",
            "status": "F",
            "inputs": {"amount": "0x2A"},
            "env": {"msg.sender": "7"},
            "entry_storage": {"y$17": "4"},
            "final_state": {"y$17": "73"},
        }, {
            "condition": "C:f:path:3#r2_boundary_return",
            "status": "F",
            "return_value_known": True,
            "return_value": "12",
        }, {
            "condition": "unrelated",
            "status": "F",
            "final_state": {"y$17": "999"},
        }]
    }
    observations = r2_refutation_observations(log, report)
    bad = 0
    bad += check(observations[("y", "post in [5, 50]")] == {
        "post": "73",
        "pre": "4",
        "claim": report["claims"][0],
        "ce": {
            "amount": "0x2A",
            "msg.sender": "7",
            "state.y$17": "4",
        },
    },
                 f"state values come from the exact failed claim: {observations}")
    bad += check(observations[("return", "return in [1, 9]")] == {
        "post": "12",
        "pre": None,
        "claim": report["claims"][1],
        "ce": {
            "return": "12",
        },
    }, f"return values are bound to the return candidate: {observations}")
    bad += check(len(observations) == 2, "an unrelated CE is never borrowed")
    coordinates = claim_oracle_coordinate_values(report["claims"][0],
                                                  ["amount", "msg.sender", "state.y"])
    bad += check(coordinates == {"amount": 42, "msg.sender": 7, "state.y": 4},
                 f"the failed claim exposes one complete renderable input point: {coordinates}")
    bad += check(claim_oracle_coordinate_values(report["claims"][0],
                                                ["amount", "block.timestamp"]) is None,
                 "a missing coordinate refuses partitioning instead of inventing a value")
    bad += check(r2_subfamily_for_rung("post >= pre") == "R2.1",
                 "direction relations are reported as R2.1")
    bad += check(r2_subfamily_for_rung("post in [5, 50]", "R2.2") == "R2.2",
                 "boundary-observation provenance is reported as R2.2")
    bad += check(r2_subfamily_for_rung("post == amount", "R2.3") == "R2.3",
                 "source and typed relations are reported as R2.3")
    return bad


def test_R2_candidate_dedup_uses_safe_normalized_text_before_fuzz():
    from solidity_path_put import (
        dedup_r2_specs_by_normalized_text,  # noqa: E402
        r2_candidates)
    specs = [{
        "param":
        "batch",
        "stage":
        1,
        "kind":
        "typed",
        "candidate_count":
        8,
        "vars": [{
            "name":
            "slot",
            "equals": [
                {
                    "id": "e0",
                    "term": {
                        "kind": "coord",
                        "name": "n"
                    }
                },
                {
                    "id": "e1",
                    "term": {
                        "kind": "op",
                        "op": "add",
                        "lhs": {
                            "kind": "coord",
                            "name": "n"
                        },
                        "rhs": {
                            "kind": "coord",
                            "name": "msg.value"
                        }
                    }
                },
                {
                    "id": "e2",
                    "term": {
                        "kind": "coord",
                        "name": "_claimTopic"
                    }
                },
            ],
            "abs": [
                {
                    "id": "a0",
                    "lo": {
                        "kind": "coord",
                        "name": "n"
                    },
                    "hi": {
                        "kind": "coord",
                        "name": "n"
                    }
                },
                {
                    "id": "a1",
                    "lo": {
                        "kind": "op",
                        "op": "sub",
                        "lhs": {
                            "kind": "coord",
                            "name": "n"
                        },
                        "rhs": {
                            "kind": "coord",
                            "name": "msg.value"
                        }
                    },
                    "hi": {
                        "kind": "op",
                        "op": "sub",
                        "lhs": {
                            "kind": "coord",
                            "name": "n"
                        },
                        "rhs": {
                            "kind": "coord",
                            "name": "msg.value"
                        }
                    }
                },
            ],
            "deltas": [
                {
                    "id": "d0",
                    "dir": "inc",
                    "lo": {
                        "kind": "coord",
                        "name": "n"
                    },
                    "hi": {
                        "kind": "coord",
                        "name": "n"
                    }
                },
                {
                    "id": "d1",
                    "dir": "inc",
                    "lo": {
                        "kind": "op",
                        "op": "add",
                        "lhs": {
                            "kind": "coord",
                            "name": "msg.value"
                        },
                        "rhs": {
                            "kind": "coord",
                            "name": "n"
                        }
                    },
                    "hi": {
                        "kind": "op",
                        "op": "add",
                        "lhs": {
                            "kind": "coord",
                            "name": "msg.value"
                        },
                        "rhs": {
                            "kind": "coord",
                            "name": "n"
                        }
                    }
                },
            ],
        }]
    }]
    said = []
    got, dropped = dedup_r2_specs_by_normalized_text(specs, {"msg.value": 0}, log=said.append)
    texts = [candidate["text"] for candidate in r2_candidates(got)]
    bad = 0
    bad += check(dropped == 3, f"three normalized duplicates are removed: "
                 f"{dropped}, {texts}")
    bad += check(
        texts == [
            "post == n",
            "post in [n, n]",
            "post - pre in [n, n] with post >= pre",
            "post == _claimTopic",
        ], f"one representative per normalized rung survives: {texts}")
    bad += check(any("before Forge/ESBMC" in line for line in said),
                 f"the log names when the drop happened: {said}")
    return bad


def test_typed_R2_is_ONE_BATCH_and_contains_pre_plus_coordinate():
    from solidity_path_put import (
        propose_r2_batch,  # noqa: E402
        r2_terms_from_specs,
        r2_term_text)
    got = propose_r2_batch(INC_ROWS, [("amount", "uint256")],
                           source_literals=("0", "7"),
                           depth=1,
                           var_bytes={"bal": 32},
                           rendered_coords=[("amount", "num", None)],
                           term_budget=96,
                           log=lambda _line: None)
    bad = 0
    bad += check(len(got) == 1, f"one path produces one R2 query: {got}")
    if not got:
        return bad + 1
    entry = got[0]["vars"][0]
    equality_terms = {r2_term_text(item["term"]) for item in entry["equals"]}
    delta_terms = {
        r2_term_text(item["lo"])
        for item in entry["deltas"] if r2_term_text(item["lo"]) == r2_term_text(item["hi"])
    }
    bad += check("(pre + amount)" in equality_terms,
                 f"post == pre + amount is asked: {sorted(equality_terms)}")
    bad += check("(amount - 7)" in delta_terms, f"delta expressions use the same grammar: "
                 f"{sorted(delta_terms)}")
    lookup = r2_terms_from_specs(got)
    bad += check("(pre + amount)" in lookup, f"the renderer receives the structured term: {lookup}")
    return bad


