def _return_chain_ast_path():

    def ident(name, ref):
        return {
            "nodeType": "Identifier",
            "name": name,
            "referencedDeclaration": ref,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def lit(value):
        return {
            "nodeType": "Literal",
            "kind": "number",
            "value": str(value),
            "typeDescriptions": {
                "typeString": f"int_const {value}"
            }
        }

    def binop(lhs, op, rhs):
        return {
            "nodeType": "BinaryOperation",
            "operator": op,
            "leftExpression": lhs,
            "rightExpression": rhs,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def cond(value):
        return binop(ident("y", 5), "==", lit(value))

    def ret(expr):
        return {"nodeType": "Return", "expression": expr}

    def ifret(value, expr):
        return {
            "nodeType": "IfStatement",
            "condition": cond(value),
            "trueBody": {
                "nodeType": "Block",
                "statements": [ret(expr)]
            }
        }

    fn = {
        "nodeType": "FunctionDefinition",
        "id": 36,
        "name": "add",
        "parameters": {
            "parameters": [
                {
                    "nodeType": "VariableDeclaration",
                    "id": 3,
                    "name": "x",
                    "typeDescriptions": {
                        "typeString": "uint256"
                    }
                },
                {
                    "nodeType": "VariableDeclaration",
                    "id": 5,
                    "name": "y",
                    "typeDescriptions": {
                        "typeString": "uint256"
                    }
                },
            ]
        },
        "returnParameters": {
            "parameters": [
                {
                    "nodeType": "VariableDeclaration",
                    "id": 8,
                    "name": "",
                    "typeDescriptions": {
                        "typeString": "uint256"
                    }
                },
            ]
        },
        "body": {
            "nodeType":
            "Block",
            "statements": [
                ifret(0, ident("x", 3)),
                ifret(
                    1, {
                        "nodeType": "UnaryOperation",
                        "operator": "++",
                        "prefix": True,
                        "subExpression": ident("x", 3),
                        "typeDescriptions": {
                            "typeString": "uint256"
                        }
                    }),
                ifret(2, binop(ident("x", 3), "+", lit(2))),
                ret(binop(ident("x", 3), "+", ident("y", 5))),
            ]
        },
    }
    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType": "ContractDefinition",
            "id": 84,
            "name": "Cr1",
            "linearizedBaseContracts": [84],
            "nodes": [fn],
        }]
    }
    f = tempfile.NamedTemporaryFile("w", suffix=".solast", delete=False)
    json.dump(ast, f)
    f.close()
    return f.name


def test_normal_exit_retreat_bounds_prefix_increment_return():
    from solidity_path_put import UINT256_MAX  # noqa: E402
    ast = _return_chain_ast_path()
    region = {"x": ["0", str(UINT256_MAX)], "y": ["1", "1"], "msg.value": ["0", "0"]}
    new_region, holes, notes = normal_exit_region_retreat(ast,
                                                          "Cr1",
                                                          "add", [{
                                                              "branch_claim": "y == 0"
                                                          }, {
                                                              "branch_claim": "!(y == 1)"
                                                          }],
                                                          region, {}, [("x", "uint256"),
                                                                       ("y", "uint256")],
                                                          arity=2,
                                                          declaration_id=36,
                                                          rettypes=[("", "uint256")])
    bad = 0
    bad += check(new_region["x"] == [0, UINT256_MAX - 1],
                 f"++x normal exit narrows x below max: {new_region}")
    bad += check(new_region["y"] == ["1", "1"], f"the branch coordinate stays pinned: {new_region}")
    bad += check(holes == {}, f"no holes introduced: {holes}")
    bad += check(notes and "normal-exit arithmetic retreat" in notes[0],
                 f"the retreat is disclosed: {notes}")
    os.unlink(ast)
    return bad


