def test_path_decision_guard_splits_safe_boolean_shapes():
    bad = 0
    bad += check(
        path_conditions_from_branch_claim("!(_chosenNumber > 0 && _chosenNumber <= 100)") == [
            ("_chosenNumber", ">", "0"),
            ("_chosenNumber", "<=", "100"),
        ], "negated conjunction means this path walked both conjuncts")
    bad += check(
        path_conditions_from_branch_claim("!((_chosenNumber > 0 && _chosenNumber <= 100))") == [
            ("_chosenNumber", ">", "0"),
            ("_chosenNumber", "<=", "100"),
        ], "extra outer parentheses do not hide the top-level conjunction")
    lines, skipped = path_decision_assumes(
        [{
            "branch_claim": "!(_chosenNumber > 0 && _chosenNumber <= 100)"
        }], {"_chosenNumber": "chosen"})
    bad += check(
        lines == [
            ("!(_chosenNumber > 0 && _chosenNumber <= 100)", "    vm.assume(chosen > 0);"),
            ("!(_chosenNumber > 0 && _chosenNumber <= 100)", "    vm.assume(chosen <= 100);"),
        ] and skipped == [],
        f"safe conjunction path guard renders both assumes: {lines}, {skipped}")
    bad += check(
        path_conditions_from_branch_claim("proposalId > proposalCount || proposalId == 0") == [
            ("proposalId", "<=", "proposalCount"),
            ("proposalId", "!=", "0"),
        ], "plain disjunction means this path walked both negated arms")
    bad += check(
        path_conditions_from_branch_claim(
            "msg.sender != InstanceBuyer && msg.sender != InstanceOwner") is None,
        "a disjunctive walked guard is not flattened into conjunctions")
    bad += check(
        path_conditions_from_branch_claim(
            "(msg.sender != InstanceBuyer && msg.sender != InstanceOwner)") is None,
        "outer parentheses keep a disjunctive walked guard grouped")
    lines, skipped = path_decision_assumes(
        [{
            "branch_claim": "msg.sender != InstanceBuyer && msg.sender != InstanceOwner"
        }], {
            "msg.sender": "sender",
            "state.InstanceBuyer": "_pre_buyer",
            "state.InstanceOwner": "_pre_owner"
        })
    bad += check(
        lines == [("msg.sender != InstanceBuyer && msg.sender != InstanceOwner",
                   "    vm.assume((sender == _pre_buyer || sender == _pre_owner));")]
        and skipped == [], f"false conjunction renders as a disjunctive assume: "
        f"{lines}, {skipped}")
    lines, skipped = path_decision_assumes(
        [{
            "branch_claim": "!(msg.sender == owner || members[msg.sender] == 1)"
        }], {
            "msg.sender": "sender",
            "state.owner": "_pre_owner",
            "state.members[msg.sender]": "_pre_member"
        })
    bad += check(
        lines == [("!(msg.sender == owner || members[msg.sender] == 1)",
                   "    vm.assume((sender == _pre_owner || _pre_member == 1));")] and skipped == [],
        f"true disjunction renders as one OR assume: {lines}, {skipped}")
    bad += check(
        path_condition_terms_from_branch_claim("!(proposalId > proposalCount || proposalId == 0)")
        == ["proposalId", "proposalCount", "proposalId",
            "0"], "grouped disjunction exposes every term for guard materialization")
    lines, skipped = path_decision_assumes(
        [{
            "branch_claim": "!(msg.sender == _owner || (_owners[msg.sender]) == 1)"
        }], {
            "msg.sender": "sender",
            "state._owner": "_pre_owner",
            "state._owners[msg.sender]": "_pre_owner_slot"
        })
    bad += check(
        lines == [("!(msg.sender == _owner || (_owners[msg.sender]) == 1)",
                   "    vm.assume((sender == _pre_owner || _pre_owner_slot == 1));")]
        and skipped == [], f"parenthesized mapping term in OR guard renders: {lines}, {skipped}")
    return bad


