def test_source_R2_mines_modifier_suffix_effects_only():
    from solidity_path_put import r2_term_text, source_assignment_r2_specs  # noqa: E402

    def ident(ref, name, ty="uint256"):
        return {
            "nodeType": "Identifier",
            "referencedDeclaration": ref,
            "name": name,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def num(value):
        return {
            "nodeType": "Literal",
            "kind": "number",
            "value": str(value),
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def assign(rhs_ref, rhs_name, src):
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": "=",
                "src": src,
                "leftHandSide": ident(10, "_status", "uint256"),
                "rightHandSide": ident(rhs_ref, rhs_name, "uint256")
            }
        }

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [
                {
                    "nodeType": "VariableDeclaration",
                    "id": 10,
                    "name": "_status",
                    "stateVariable": True,
                    "typeDescriptions": {
                        "typeString": "uint256"
                    }
                },
                {
                    "nodeType": "VariableDeclaration",
                    "id": 11,
                    "name": "_ENTERED",
                    "stateVariable": True,
                    "constant": True,
                    "typeDescriptions": {
                        "typeString": "uint256"
                    },
                    "value": num(2)
                },
                {
                    "nodeType": "VariableDeclaration",
                    "id": 12,
                    "name": "_NOT_ENTERED",
                    "stateVariable": True,
                    "constant": True,
                    "typeDescriptions": {
                        "typeString": "uint256"
                    },
                    "value": num(1)
                },
                {
                    "nodeType": "ModifierDefinition",
                    "id": 30,
                    "name": "nonReentrant",
                    "parameters": {
                        "parameters": []
                    },
                    "body": {
                        "nodeType":
                        "Block",
                        "statements": [
                            assign(11, "_ENTERED", "100:12:0"), {
                                "nodeType": "PlaceholderStatement"
                            },
                            assign(12, "_NOT_ENTERED", "130:16:0")
                        ]
                    }
                },
                {
                    "nodeType":
                    "FunctionDefinition",
                    "id":
                    20,
                    "name":
                    "touch",
                    "parameters": {
                        "parameters": []
                    },
                    "modifiers": [{
                        "nodeType": "ModifierInvocation",
                        "modifierName": {
                            "nodeType": "Identifier",
                            "referencedDeclaration": 30,
                            "name": "nonReentrant"
                        },
                        "arguments": []
                    }],
                    "body": {
                        "nodeType": "Block",
                        "statements": []
                    }
                },
            ]
        }]
    }
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out:
        json.dump(ast, out)
    try:
        specs, evidence = source_assignment_r2_specs(path,
                                                     "C",
                                                     "touch", [], {"_status": (0, 0, 32)}, [],
                                                     arity=0,
                                                     maps={},
                                                     log=lambda _msg: None)
    finally:
        os.unlink(path)

    entries = {entry["name"]: entry for entry in specs[0]["vars"]} \
        if specs else {}
    equals = [r2_term_text(item["term"]) for item in entries.get("_status", {}).get("equals", [])]
    bad = 0
    bad += check(equals == ["1"], f"modifier suffix, not prefix, is mined: {entries}")
    bad += check(any("_status: post == _NOT_ENTERED" in line for line in evidence),
                 f"modifier suffix provenance is recorded: {evidence}")
    bad += check(not any("_status: post == _ENTERED" in line for line in evidence),
                 f"modifier prefix is not treated as final state: {evidence}")
    return bad


def test_source_R2_arithmetic_assignments_prioritize_expression_endpoints():
    from solidity_path_put import (
        r2_term_text,  # noqa: E402
        source_assignment_r2_specs)

    def ident(ref, name):
        return {"nodeType": "Identifier", "referencedDeclaration": ref, "name": name}

    def num(value):
        return {"nodeType": "Literal", "kind": "number", "value": str(value)}

    def binop(op, lhs, rhs):
        return {
            "nodeType": "BinaryOperation",
            "operator": op,
            "leftExpression": lhs,
            "rightExpression": rhs,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    msg_sender = {
        "nodeType": "MemberAccess",
        "memberName": "sender",
        "expression": {
            "nodeType": "Identifier",
            "name": "msg"
        },
        "typeDescriptions": {
            "typeString": "address"
        }
    }
    msg_value = {
        "nodeType": "MemberAccess",
        "memberName": "value",
        "expression": {
            "nodeType": "Identifier",
            "name": "msg"
        },
        "typeDescriptions": {
            "typeString": "uint256"
        }
    }
    quote_sender = {
        "nodeType": "IndexAccess",
        "baseExpression": ident(15, "quote"),
        "indexExpression": msg_sender,
        "typeDescriptions": {
            "typeString": "uint256"
        }
    }

    def assign(ref_or_lhs, rhs, src):
        lhs = ref_or_lhs if isinstance(ref_or_lhs, dict) else ident(ref_or_lhs[0], ref_or_lhs[1])
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": "=",
                "src": src,
                "leftHandSide": lhs,
                "rightHandSide": rhs
            }
        }

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [{
                "nodeType": "VariableDeclaration",
                "id": 10,
                "name": "fee",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 11,
                "name": "scaled",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 12,
                "name": "paidLess",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 13,
                "name": "half",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 14,
                "name": "broken",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 15,
                "name": "quote",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "mapping(address => uint256)"
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 20,
                "name": "calc",
                "parameters": {
                    "parameters": [{
                        "id": 21,
                        "name": "amount",
                        "typeDescriptions": {
                            "typeString": "uint256"
                        }
                    }]
                },
                "body": {
                    "nodeType":
                    "Block",
                    "statements": [
                        assign((10, "fee"), binop("+", ident(21, "amount"), num(7)), "100:12:0"),
                        assign((11, "scaled"), binop("*", num(2), ident(21, "amount")), "120:12:0"),
                        assign((12, "paidLess"), binop("-", msg_value, num(1)), "140:12:0"),
                        assign((13, "half"), binop("/", ident(21, "amount"), num(2)), "160:12:0"),
                        assign((14, "broken"), binop("/", ident(21, "amount"), num(0)), "180:12:0"),
                        assign(quote_sender, binop("*", ident(21, "amount"), num(3)), "200:12:0")
                    ]
                }
            }]
        }]
    }
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out:
        json.dump(ast, out)
    try:
        specs, evidence = source_assignment_r2_specs(
            path,
            "C",
            "calc", [("amount", "uint256")], {
                "fee": (0, 0, 32),
                "scaled": (1, 0, 32),
                "paidLess": (2, 0, 32),
                "half": (3, 0, 32),
                "broken": (4, 0, 32)
            }, [("amount", "num", None), ("msg.value", "num", None)],
            arity=1,
            maps={"quote": (5, "address", 32, 0, "quote", None)},
            log=lambda _msg: None)
        unrendered, _ = source_assignment_r2_specs(
            path,
            "C",
            "calc", [("amount", "uint256")], {
                "fee": (0, 0, 32),
                "scaled": (1, 0, 32),
                "paidLess": (2, 0, 32),
                "half": (3, 0, 32),
                "broken": (4, 0, 32)
            }, [],
            arity=1,
            maps={"quote": (5, "address", 32, 0, "quote", None)},
            log=lambda _msg: None)
    finally:
        os.unlink(path)

    entries = {entry["name"]: entry for entry in specs[0]["vars"]} if specs else {}

    def equal_text(name):
        return [r2_term_text(item["term"]) for item in entries.get(name, {}).get("equals", [])]

    bad = 0
    bad += check(
        equal_text("fee") == ["(amount + 7)"], f"amount + literal endpoint is mined: {entries}")
    bad += check(
        equal_text("scaled") == ["(2 * amount)"], f"literal * amount endpoint is mined: {entries}")
    bad += check(
        equal_text("paidLess") == ["(msg.value - 1)"],
        f"msg.value - literal endpoint is mined: {entries}")
    bad += check(
        equal_text("half") == ["(amount / 2)"],
        f"division by nonzero literal endpoint is mined: {entries}")
    bad += check("broken" not in entries,
                 f"division by zero is not mined as an endpoint: {entries}")
    bad += check(
        equal_text("quote[msg.sender]") == ["(amount * 3)"],
        f"mapping arithmetic endpoint is mined: {entries}")
    bad += check(any("fee: post == (amount + 7)" in line for line in evidence),
                 f"scalar arithmetic provenance is recorded: {evidence}")
    bad += check(any("quote[msg.sender]: post == (amount * 3)" in line for line in evidence),
                 f"mapping arithmetic provenance is recorded: {evidence}")
    bad += check(unrendered == [], f"arithmetic endpoints do not mine unrendered coords: "
                 f"{unrendered}")
    return bad


def test_source_R2_state_entry_coords_are_used_only_when_rendered():
    from solidity_path_put import r2_term_text, source_assignment_r2_specs  # noqa: E402

    def ident(ref, name, ty="uint256"):
        return {
            "nodeType": "Identifier",
            "referencedDeclaration": ref,
            "name": name,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def num(value):
        return {"nodeType": "Literal", "kind": "number", "value": str(value)}

    def binop(op, lhs, rhs):
        return {
            "nodeType": "BinaryOperation",
            "operator": op,
            "leftExpression": lhs,
            "rightExpression": rhs,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def assign(ref, name, rhs, src, op="="):
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": op,
                "src": src,
                "leftHandSide": ident(ref, name),
                "rightHandSide": rhs
            }
        }

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [{
                "nodeType": "VariableDeclaration",
                "id": 10,
                "name": "seed",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 11,
                "name": "mirror",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 12,
                "name": "next",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 13,
                "name": "total",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 14,
                "name": "owner",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "address"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 15,
                "name": "savedOwner",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "address"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 16,
                "name": "ready",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "bool"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 17,
                "name": "copiedReady",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "bool"
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 20,
                "name": "copy",
                "parameters": {
                    "parameters": [{
                        "id": 21,
                        "name": "amount",
                        "typeDescriptions": {
                            "typeString": "uint256"
                        }
                    }]
                },
                "body": {
                    "nodeType":
                    "Block",
                    "statements": [
                        assign(11, "mirror", ident(10, "seed"), "100:12:0"),
                        assign(12, "next", binop("+", ident(10, "seed"), ident(21, "amount")),
                               "120:12:0"),
                        assign(13, "total", ident(10, "seed"), "140:12:0", "+="),
                        assign(15, "savedOwner", ident(14, "owner", "address"), "160:12:0"),
                        assign(17, "copiedReady", ident(16, "ready", "bool"), "180:12:0"),
                        assign(12, "next", binop("/", ident(10, "seed"), num(0)), "200:12:0")
                    ]
                }
            }]
        }]
    }
    layout = {
        "seed": (0, 0, 32),
        "mirror": (1, 0, 32),
        "next": (2, 0, 32),
        "total": (3, 0, 32),
        "owner": (4, 0, 20),
        "savedOwner": (5, 0, 20),
        "ready": (6, 0, 1),
        "copiedReady": (7, 0, 1)
    }
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out:
        json.dump(ast, out)
    try:
        specs, evidence = source_assignment_r2_specs(path,
                                                     "C",
                                                     "copy", [("amount", "uint256")],
                                                     layout, [("amount", "num", None),
                                                              ("state.seed", "num", None),
                                                              ("state.owner", "id", 20),
                                                              ("state.ready", "bool", 1)],
                                                     arity=1,
                                                     log=lambda _msg: None)
        unrendered, _ = source_assignment_r2_specs(path,
                                                   "C",
                                                   "copy", [("amount", "uint256")],
                                                   layout, [("amount", "num", None)],
                                                   arity=1,
                                                   log=lambda _msg: None)
    finally:
        os.unlink(path)

    entries = {entry["name"]: entry for entry in specs[0]["vars"]} if specs else {}

    def equals(name):
        return [r2_term_text(item["term"]) for item in entries.get(name, {}).get("equals", [])]

    total_deltas = entries.get("total", {}).get("deltas", [])
    bad = 0
    bad += check(
        equals("mirror") == ["state.seed"], f"state.seed direct endpoint is mined: {entries}")
    bad += check(
        equals("next") == ["(state.seed + amount)"],
        f"state.seed arithmetic endpoint is mined and divide-by-zero "
        f"is skipped: {entries}")
    bad += check(
        len(total_deltas) == 1 and r2_term_text(total_deltas[0]["lo"]) == "state.seed",
        f"state.seed delta endpoint is mined: {total_deltas}")
    bad += check(
        equals("savedOwner") == ["state.owner"], f"state.owner id endpoint is mined: {entries}")
    bad += check(
        equals("copiedReady") == ["state.ready"], f"state.ready bool endpoint is mined: {entries}")
    bad += check(any("mirror: post == state.seed" in line for line in evidence),
                 f"state coord provenance is recorded: {evidence}")
    bad += check(any("total: post - pre == state.seed" in line for line in evidence),
                 f"state delta provenance is recorded: {evidence}")
    unrendered_entries = ({
        entry["name"]: entry
        for entry in unrendered[0]["vars"]
    } if unrendered else {})
    bad += check(
        set(unrendered_entries) == {"mirror", "savedOwner", "copiedReady"},
        f"direct readable state coords materialize without enabling composites: {unrendered}")
    return bad


def test_source_R2_type_conversion_wrappers_are_unwrapped_conservatively():
    from solidity_path_put import r2_term_text, source_assignment_r2_specs  # noqa: E402

    def ident(ref, name, ty):
        return {
            "nodeType": "Identifier",
            "referencedDeclaration": ref,
            "name": name,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def num(value):
        return {"nodeType": "Literal", "kind": "number", "value": str(value)}

    def cast(ty, arg):
        return {
            "nodeType": "FunctionCall",
            "kind": "typeConversion",
            "typeDescriptions": {
                "typeString": ty
            },
            "expression": {
                "nodeType": "ElementaryTypeNameExpression",
                "typeName": {
                    "nodeType": "ElementaryTypeName",
                    "name": ty
                }
            },
            "arguments": [arg]
        }

    def binop(op, lhs, rhs):
        return {
            "nodeType": "BinaryOperation",
            "operator": op,
            "leftExpression": lhs,
            "rightExpression": rhs,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def assign(ref_or_lhs, rhs, src, op="="):
        if isinstance(ref_or_lhs, dict):
            lhs = ref_or_lhs
        else:
            ref, name, ty = ref_or_lhs
            lhs = ident(ref, name, ty)
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": op,
                "src": src,
                "leftHandSide": lhs,
                "rightHandSide": rhs
            }
        }

    msg_sender = {
        "nodeType": "MemberAccess",
        "memberName": "sender",
        "expression": {
            "nodeType": "Identifier",
            "name": "msg"
        },
        "typeDescriptions": {
            "typeString": "address"
        }
    }
    msg_value = {
        "nodeType": "MemberAccess",
        "memberName": "value",
        "expression": {
            "nodeType": "Identifier",
            "name": "msg"
        },
        "typeDescriptions": {
            "typeString": "uint256"
        }
    }
    quote_sender = {
        "nodeType": "IndexAccess",
        "baseExpression": ident(17, "quote", "mapping(address => uint256)"),
        "indexExpression": msg_sender,
        "typeDescriptions": {
            "typeString": "uint256"
        }
    }
    amount = ident(21, "amount", "uint256")
    who = ident(22, "who", "address")

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [{
                "nodeType": "VariableDeclaration",
                "id": 10,
                "name": "small",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint128"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 11,
                "name": "wide",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 12,
                "name": "total",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 13,
                "name": "calc",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 14,
                "name": "owner",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "address"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 15,
                "name": "payableOwner",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "address"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 16,
                "name": "paid",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "uint256"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 17,
                "name": "quote",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "mapping(address => uint256)"
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 20,
                "name": "wrap",
                "parameters": {
                    "parameters": [{
                        "id": 21,
                        "name": "amount",
                        "typeDescriptions": {
                            "typeString": "uint256"
                        }
                    }, {
                        "id": 22,
                        "name": "who",
                        "typeDescriptions": {
                            "typeString": "address"
                        }
                    }]
                },
                "body": {
                    "nodeType":
                    "Block",
                    "statements": [
                        assign((10, "small", "uint128"), cast("uint128", amount), "100:12:0"),
                        assign((11, "wide", "uint256"), cast("uint128", amount), "120:12:0"),
                        assign((12, "total", "uint256"), cast("uint256", amount), "140:12:0", "+="),
                        assign((13, "calc", "uint256"),
                               binop("+", cast("uint256", amount), cast("uint256", num(7))),
                               "160:12:0"),
                        assign((14, "owner", "address"), cast("address", who), "180:12:0"),
                        assign((15, "payableOwner", "address"), cast("address payable", who),
                               "200:12:0"),
                        assign((16, "paid", "uint256"), cast("uint256", msg_value), "220:12:0"),
                        assign(quote_sender, cast("uint256", amount), "240:12:0")
                    ]
                }
            }]
        }]
    }
    layout = {
        "small": (0, 0, 16),
        "wide": (1, 0, 32),
        "total": (2, 0, 32),
        "calc": (3, 0, 32),
        "owner": (4, 0, 20),
        "payableOwner": (5, 0, 20),
        "paid": (6, 0, 32)
    }
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out:
        json.dump(ast, out)
    try:
        specs, evidence = source_assignment_r2_specs(
            path,
            "C",
            "wrap", [("amount", "uint256"), ("who", "address")],
            layout, [("amount", "num", None), ("who", "id", 20), ("msg.value", "num", None)],
            arity=2,
            maps={"quote": (7, "address", 32, 0, "quote", None)},
            log=lambda _msg: None)
    finally:
        os.unlink(path)

    entries = {entry["name"]: entry for entry in specs[0]["vars"]} if specs else {}

    def equals(name):
        return [r2_term_text(item["term"]) for item in entries.get(name, {}).get("equals", [])]

    total_deltas = entries.get("total", {}).get("deltas", [])
    bad = 0
    bad += check(equals("small") == ["amount"], f"same-target uint128(amount) is mined: {entries}")
    bad += check("wide" not in entries, f"uint128(amount) assigned to uint256 is not simplified: "
                 f"{entries}")
    bad += check(
        len(total_deltas) == 1 and r2_term_text(total_deltas[0]["lo"]) == "amount",
        f"cast-wrapped += amount is mined: {total_deltas}")
    bad += check(
        equals("calc") == ["(amount + 7)"],
        f"cast-wrapped arithmetic operands are mined: {entries}")
    bad += check(equals("owner") == ["who"], f"address(who) endpoint is mined: {entries}")
    bad += check(
        equals("payableOwner") == ["who"], f"address payable cast endpoint is mined: {entries}")
    bad += check(
        equals("paid") == ["msg.value"], f"uint256(msg.value) endpoint is mined: {entries}")
    bad += check(
        equals("quote[msg.sender]") == ["amount"],
        f"cast-wrapped mapping endpoint is mined: {entries}")
    bad += check(any("calc: post == (amount + 7)" in line for line in evidence),
                 f"cast arithmetic provenance is recorded: {evidence}")
    return bad


