                        assign(index(10, "count", num(7)), ident(21, "amount"), "100:12:0"),
                        assign(index(11, "flagged", boolean(True)), ident(21, "amount"), "120:12:0",
                               "+="),
                        assign(index(12, "owners", address_num(1)), ident(21, "amount"),
                               "140:12:0"),
                        assign(index(13, "hexOwners", hex_lit("12ab")), ident(21, "amount"),
                               "160:12:0"),
