def test_storage_layout_expands_struct_mapping_members():
    from solidity_path_put import (  # noqa: E402
        _storage_layout_struct_mappings, assert_query_pins, assert_query_region_entries,
        esbmc_certifiable_maps, parse_slot_name, propose_slot_vars, region_slot_vars)

    types = {
        "t_address": {
            "encoding": "inplace",
            "label": "address",
            "numberOfBytes": "20"
        },
        "t_uint256": {
            "encoding": "inplace",
            "label": "uint256",
            "numberOfBytes": "32"
        },
        "t_uint8": {
            "encoding": "inplace",
            "label": "uint8",
            "numberOfBytes": "1"
        },
        "t_bal": {
            "encoding":
            "inplace",
            "label":
            "struct C.Bal",
            "numberOfBytes":
            "32",
            "members": [{
                "label": "amount",
                "slot": "0",
                "offset": "0",
                "type": "t_uint256"
            }, {
                "label": "tag",
                "slot": "0",
                "offset": "31",
                "type": "t_uint8"
            }]
        },
        "t_map": {
            "encoding": "mapping",
            "key": "t_address",
            "value": "t_bal"
        },
    }
    members = [{"label": "userDeposits", "slot": "2", "offset": "0", "type": "t_map"}]
    maps = _storage_layout_struct_mappings("vault", "7", members, types)
    parsed = parse_slot_name("vault.userDeposits[who].amount")
    log = []
    proposed = propose_slot_vars(maps, [("who", "address"), ("amount", "uint256")], log=log.append)
    region = {"state.vault.userDeposits[who].amount": (1, 2)}
    pins = {"state.vault.userDeposits[who].amount": 1}
    query_region, skipped_region = assert_query_region_entries(region, {}, {}, maps)
    query_pins, skipped_pins = assert_query_pins(pins, {}, maps)

    bad = 0
    bad += check(
        maps == {
            "vault.userDeposits.amount": (9, "address", 32, 0, "vault.userDeposits", "amount"),
            "vault.userDeposits.tag": (9, "address", 1, 31, "vault.userDeposits", "tag"),
        }, f"struct-contained mapping fields are layout coords: {maps}")
    bad += check(parsed == ("vault.userDeposits", ["who"], ".amount"),
                 f"dotted mapping base is parsed without eating tail: {parsed}")
    bad += check(
        esbmc_certifiable_maps(maps) == {},
        f"struct-contained mappings are not ESBMC-queryable yet: "
        f"{esbmc_certifiable_maps(maps)}")
    bad += check(
        proposed == [], f"struct-contained mapping fields are not proposed to "
        f"--path-cov-assert yet: {proposed}")
    bad += check(
        region_slot_vars(region, maps) == [],
        "certified-region dotted slots are not reused before ESBMC "
        "can certify them")
    bad += check(
        query_region == [] and query_pins == {}, f"dotted mapping region/pins are not passed to "
        f"--path-cov-assert: {query_region}, {query_pins}")
    bad += check(skipped_region and skipped_pins,
                 f"dotted mapping skips are reported: {skipped_region}, "
                 f"{skipped_pins}")
    bad += check(any("struct-contained mapping_t fields" in line for line in log),
                 f"skipped struct-contained mapping says why: {log}")
    return bad


def test_storage_layout_keeps_nonzero_mapping_value_struct_member_slots():
    from solidity_path_put import (  # noqa: E402
        _storage_layout_mapping_entries, assert_query_region_entries, esbmc_certifiable_maps,
        map_value_slot_expr, propose_slot_vars, source_access_slot_vars)

    types = {
        "t_address": {
            "encoding": "inplace",
            "label": "address",
            "numberOfBytes": "20"
        },
        "t_bool": {
            "encoding": "inplace",
            "label": "bool",
            "numberOfBytes": "1"
        },
        "t_bytes32": {
            "encoding": "inplace",
            "label": "bytes32",
            "numberOfBytes": "32"
        },
        "t_members": {
            "encoding": "mapping",
            "key": "t_address",
            "value": "t_bool"
        },
    }
    role_data = {
        "encoding":
        "inplace",
        "numberOfBytes":
        "64",
        "members": [{
            "label": "members",
            "slot": "0",
            "offset": "0",
            "type": "t_members"
        }, {
            "label": "adminRole",
            "slot": "1",
            "offset": "0",
            "type": "t_bytes32"
        }]
    }
    maps = _storage_layout_mapping_entries("_roles", "0", "bytes32", role_data, types)
    spec = (0, "bytes32", 32, 0, "_roles", "adminRole", 1)
    region, skipped = assert_query_region_entries({"state._roles[role].adminRole": (0, 0)}, {}, {},
                                                  maps, [("role", "bytes32")])
    bad = 0
    bad += check(maps == {"_roles.adminRole": spec},
                 f"nonzero member slot is retained while aggregate member is skipped: {maps}")
    bad += check(
        esbmc_certifiable_maps(maps) == maps,
        f"top-level mapping member remains ESBMC-queryable: {maps}")
    bad += check(
        propose_slot_vars(maps, [("role", "bytes32")]) == ["_roles[role].adminRole"],
        f"the source member is proposed to the ladder: {maps}")
    source_vars, used, source_skipped = source_access_slot_vars([("_roles.adminRole", ("role", ))],
                                                                maps, [("role", "bytes32")])
    bad += check(
        source_vars == ["_roles[role].adminRole"] and used == {"_roles.adminRole"}
        and source_skipped == [], f"the exact source access has priority: {source_vars}, {used}, "
        f"{source_skipped}")
    bad += check(
        region == [{
            "name": "state._roles[role].adminRole",
            "lo": "0",
            "hi": "0"
        }] and skipped == [], f"the exact member region reaches the ladder: {region}, {skipped}")
    bad += check(
        map_value_slot_expr(
            ["role"], spec) == "bytes32(uint256(keccak256(abi.encode(role, uint256(0)))) + 1)",
        f"Foundry reads the struct member at mapping hash plus one: "
        f"{map_value_slot_expr(['role'], spec)}")
    bad += check(
        map_value_slot_expr(["role"], spec[:6]) == "keccak256(abi.encode(role, uint256(0)))",
        "slot-zero scalar mapping rendering stays byte-identical")
    return bad


def test_source_R2_struct_mapping_members_wait_for_ESBMC_support():
    from solidity_path_put import source_assignment_r2_specs  # noqa: E402

    def ident(ref, name, ty="uint256"):
        return {
            "nodeType": "Identifier",
            "referencedDeclaration": ref,
            "name": name,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def member(base, name, ty="uint256"):
        return {
            "nodeType": "MemberAccess",
            "memberName": name,
            "expression": base,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def index(base, key, ty="struct C.Bal storage ref"):
        return {
            "nodeType": "IndexAccess",
            "baseExpression": base,
            "indexExpression": key,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def local_decl(ref, name, ty, value):
        return {
            "nodeType":
            "VariableDeclarationStatement",
            "declarations": [{
                "nodeType": "VariableDeclaration",
                "id": ref,
                "name": name,
                "storageLocation": "storage",
                "typeDescriptions": {
                    "typeString": ty
                }
            }],
            "initialValue":
            value
        }

    def assign(lhs, rhs, src):
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": "=",
                "src": src,
                "leftHandSide": lhs,
                "rightHandSide": rhs
            }
        }

    def ret(expr, src):
        return {"nodeType": "Return", "src": src, "expression": expr}

    def function(fid, name, statements):
        return {
            "nodeType": "FunctionDefinition",
            "id": fid,
            "name": name,
            "parameters": {
                "parameters": [who_param, amount_param]
            },
            "returnParameters": {
                "parameters": [{
                    "id": fid + 1,
                    "name": "",
                    "typeDescriptions": {
                        "typeString": "uint256"
                    }
                }]
            },
            "body": {
                "nodeType": "Block",
                "statements": statements
            }
        }

    who_param = {"id": 21, "name": "who", "typeDescriptions": {"typeString": "address"}}
    amount_param = {"id": 22, "name": "amount", "typeDescriptions": {"typeString": "uint256"}}
    deposits = member(ident(10, "vault", "struct C.Vault"), "userDeposits",
                      "mapping(address => struct C.Bal)")
    direct_row = index(deposits, ident(21, "who", "address"))
    direct_amount = member(direct_row, "amount")
    alias_amount = member(ident(30, "row", "struct C.Bal storage pointer"), "amount")
    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [{
                "nodeType": "VariableDeclaration",
                "id": 10,
                "name": "vault",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "struct C.Vault"
                }
            },
                      function(20, "direct", [
                          assign(direct_amount, ident(22, "amount"), "100:10:0"),
                          ret(direct_amount, "120:10:0")
                      ]),
                      function(40, "viaAlias", [
                          local_decl(30, "row", "struct C.Bal storage pointer", direct_row),
                          assign(alias_amount, ident(22, "amount"), "200:10:0"),
                          ret(alias_amount, "220:10:0")
                      ])]
        }]
    }
    maps = {"vault.userDeposits.amount": (9, "address", 32, 0, "vault.userDeposits", "amount")}
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out_file:
        json.dump(ast, out_file)
    try:
        direct_specs, direct_evidence = source_assignment_r2_specs(path,
                                                                   "C",
                                                                   "direct",
                                                                   [("who", "address"),
                                                                    ("amount", "uint256")], {},
                                                                   [("who", "id", 20),
                                                                    ("amount", "num", None)],
                                                                   arity=2,
                                                                   maps=maps,
                                                                   rettypes=[("", "uint256")],
                                                                   log=lambda _msg: None)
        alias_specs, alias_evidence = source_assignment_r2_specs(path,
                                                                 "C",
                                                                 "viaAlias",
                                                                 [("who", "address"),
                                                                  ("amount", "uint256")], {},
                                                                 [("who", "id", 20),
                                                                  ("amount", "num", None)],
                                                                 arity=2,
                                                                 maps=maps,
                                                                 rettypes=[("", "uint256")],
                                                                 log=lambda _msg: None)
    finally:
        os.unlink(path)

    bad = 0
    bad += check(
        direct_specs == [], f"direct struct mapping field is not proposed before ESBMC "
        f"can certify mapping_t fields: {direct_specs}")
    bad += check(
        alias_specs == [], f"storage alias to struct mapping field is not proposed "
        f"before ESBMC can certify mapping_t fields: {alias_specs}")
    bad += check(
        direct_evidence == [] and alias_evidence == [],
        f"no source-R2 provenance is claimed for unqueryable "
        f"struct mappings: {direct_evidence + alias_evidence}")
    return bad


def test_source_R2_top_level_struct_members_are_state_coords():
    from solidity_path_put import RETURN_VAR, r2_term_text  # noqa: E402
    from solidity_path_put import source_assignment_r2_specs  # noqa: E402

    def ident(ref, name, ty="uint256"):
        return {
            "nodeType": "Identifier",
            "referencedDeclaration": ref,
            "name": name,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def member(base, name, ty="uint256"):
        return {
            "nodeType": "MemberAccess",
            "memberName": name,
            "expression": base,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def binop(op, lhs, rhs):
        return {
            "nodeType": "BinaryOperation",
            "operator": op,
            "leftExpression": lhs,
            "rightExpression": rhs,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def assign(lhs, rhs, src, op="="):
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": op,
                "src": src,
                "leftHandSide": lhs,
                "rightHandSide": rhs
            }
        }

    def ret(expr, src):
        return {"nodeType": "Return", "src": src, "expression": expr}

    def box_field(name, ty="uint256"):
        return member(ident(10, "box", "struct C.Box"), name, ty)

    amount_param = {"id": 21, "name": "amount", "typeDescriptions": {"typeString": "uint256"}}
    ok_param = {"id": 22, "name": "ok", "typeDescriptions": {"typeString": "bool"}}
    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [{
                "nodeType": "VariableDeclaration",
                "id": 10,
                "name": "box",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "struct C.Box"
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 20,
                "name": "get",
                "parameters": {
                    "parameters": []
                },
                "returnParameters": {
                    "parameters": [{
                        "id": 24,
                        "name": "",
                        "typeDescriptions": {
                            "typeString": "uint256"
                        }
                    }]
                },
                "body": {
                    "nodeType": "Block",
                    "statements": [ret(box_field("count"), "100:10:0")]
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 30,
                "name": "set",
                "parameters": {
                    "parameters": [amount_param, ok_param]
                },
                "returnParameters": {
                    "parameters": []
                },
                "body": {
                    "nodeType":
                    "Block",
                    "statements": [
                        assign(box_field("count"), ident(21, "amount"), "200:10:0"),
                        assign(box_field("flag", "bool"), ident(22, "ok", "bool"), "220:10:0")
                    ]
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 40,
                "name": "grow",
                "parameters": {
                    "parameters": [amount_param]
                },
                "returnParameters": {
                    "parameters": []
                },
                "body": {
                    "nodeType":
                    "Block",
                    "statements": [
                        assign(box_field("count"),
                               binop("+", box_field("count"), ident(21, "amount")), "300:10:0")
                    ]
                }
            }, {
                "nodeType": "FunctionDefinition",
                "id": 50,
                "name": "bump",
                "parameters": {
                    "parameters": []
                },
                "returnParameters": {
                    "parameters": []
                },
                "body": {
                    "nodeType":
                    "Block",
                    "statements": [{
                        "nodeType": "ExpressionStatement",
                        "expression": {
                            "nodeType": "UnaryOperation",
                            "operator": "++",
                            "src": "400:6:0",
                            "subExpression": box_field("count")
                        }
                    }, {
                        "nodeType": "ExpressionStatement",
                        "expression": {
                            "nodeType": "UnaryOperation",
                            "operator": "delete",
                            "src": "420:6:0",
                            "subExpression": box_field("flag", "bool")
                        }
                    }]
                }
            }]
        }]
    }
    layout = {"box.count": (3, 0, 32), "box.flag": (4, 0, 1)}
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out_file:
        json.dump(ast, out_file)
    try:
        get_specs, get_evidence = source_assignment_r2_specs(path,
                                                             "C",
                                                             "get", [],
                                                             layout, [],
                                                             arity=0,
                                                             rettypes=[("", "uint256")],
                                                             log=lambda _msg: None)
        set_specs, set_evidence = source_assignment_r2_specs(path,
                                                             "C",
                                                             "set", [("amount", "uint256"),
                                                                     ("ok", "bool")],
                                                             layout, [("amount", "num", None),
                                                                      ("ok", "bool", 1)],
                                                             arity=2,
                                                             log=lambda _msg: None)
        grow_specs, _grow_evidence = source_assignment_r2_specs(path,
                                                                "C",
                                                                "grow", [("amount", "uint256")],
                                                                layout, [("amount", "num", None)],
                                                                arity=1,
                                                                log=lambda _msg: None)
        bump_specs, _bump_evidence = source_assignment_r2_specs(path,
                                                                "C",
                                                                "bump", [],
                                                                layout, [],
                                                                arity=0,
                                                                log=lambda _msg: None)
    finally:
        os.unlink(path)

    def entries(specs):
        return {entry["name"]: entry for entry in specs[0]["vars"]} if specs else {}

    get_entry = entries(get_specs).get(RETURN_VAR, {})
    set_entries = entries(set_specs)
    grow_entry = entries(grow_specs).get("box.count", {})
    bump_entries = entries(bump_specs)
    get_terms = [r2_term_text(item["term"]) for item in get_entry.get("equals", [])]
    count_terms = [
        r2_term_text(item["term"]) for item in set_entries.get("box.count", {}).get("equals", [])
    ]
    flag_terms = [
        r2_term_text(item["term"]) for item in set_entries.get("box.flag", {}).get("equals", [])
    ]
    grow_equals = [r2_term_text(item["term"]) for item in grow_entry.get("equals", [])]
    grow_deltas = [r2_term_text(item["lo"]) for item in grow_entry.get("deltas", [])]
    bump_deltas = [
        r2_term_text(item["lo"]) for item in bump_entries.get("box.count", {}).get("deltas", [])
    ]
    bump_deletes = [
        r2_term_text(item["term"]) for item in bump_entries.get("box.flag", {}).get("equals", [])
    ]

    bad = 0
    bad += check(get_terms == ["state.box.count"],
                 f"struct getter return names the entry-state field: "
                 f"{get_specs}")
    bad += check(count_terms == ["amount"], f"struct numeric setter mines the field assignment: "
                 f"{set_specs}")
    bad += check(flag_terms == ["ok"],
                 f"struct bool setter mines the field assignment: {set_specs}")
    bad += check(grow_equals == ["(state.box.count + amount)"],
                 f"struct self-update mines a strong post endpoint: "
                 f"{grow_specs}")
    bad += check(grow_deltas == ["amount"],
                 f"struct self-update mines a delta endpoint: {grow_specs}")
    bad += check(bump_deltas == ["1"], f"struct unary increment mines a one-step delta: "
                 f"{bump_specs}")
    bad += check(bump_deletes == ["0"], f"struct delete mines a zero endpoint: {bump_specs}")
    bad += check(any("return: return == state.box.count" in line for line in get_evidence),
                 f"struct getter provenance is recorded: {get_evidence}")
    bad += check(any("box.flag: post == ok" in line for line in set_evidence),
                 f"struct setter provenance is recorded: {set_evidence}")
    return bad


def test_source_R2_storage_local_aliases_resolve_to_state_coords():
    from solidity_path_put import RETURN_VAR, r2_term_text  # noqa: E402
    from solidity_path_put import source_assignment_r2_specs  # noqa: E402

    def ident(ref, name, ty="uint256"):
        return {
            "nodeType": "Identifier",
            "referencedDeclaration": ref,
            "name": name,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def member(base, name, ty="uint256"):
        return {
            "nodeType": "MemberAccess",
            "memberName": name,
            "expression": base,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def index(base_ref, base_name, key, ty="uint256"):
        return {
            "nodeType": "IndexAccess",
            "baseExpression": ident(base_ref, base_name),
            "indexExpression": key,
            "typeDescriptions": {
                "typeString": ty
            }
        }

    def binop(op, lhs, rhs):
        return {
            "nodeType": "BinaryOperation",
            "operator": op,
            "leftExpression": lhs,
            "rightExpression": rhs,
            "typeDescriptions": {
                "typeString": "uint256"
            }
        }

    def local_decl(ref, name, ty, value, storage_location):
        return {
            "nodeType":
            "VariableDeclarationStatement",
            "declarations": [{
                "nodeType": "VariableDeclaration",
                "id": ref,
                "name": name,
                "storageLocation": storage_location,
                "typeDescriptions": {
                    "typeString": ty
                }
            }],
            "initialValue":
            value
        }

    def assign(lhs, rhs, src):
        return {
            "nodeType": "ExpressionStatement",
            "expression": {
                "nodeType": "Assignment",
                "operator": "=",
                "src": src,
                "leftHandSide": lhs,
                "rightHandSide": rhs
            }
        }

    def ret(expr, src):
        return {"nodeType": "Return", "src": src, "expression": expr}

    def function(fid, name, params, statements):
        return {
            "nodeType": "FunctionDefinition",
            "id": fid,
            "name": name,
            "parameters": {
                "parameters": params
            },
            "returnParameters": {
                "parameters": [{
                    "id": fid + 1,
                    "name": "",
                    "typeDescriptions": {
                        "typeString": "uint256"
                    }
                }]
            },
            "body": {
                "nodeType": "Block",
                "statements": statements
            }
        }

    amount_param = {"id": 21, "name": "amount", "typeDescriptions": {"typeString": "uint256"}}
    who_param = {"id": 22, "name": "who", "typeDescriptions": {"typeString": "address"}}
    box_ident = ident(10, "box", "struct C.Box storage ref")
    bal_who = index(11, "bal", ident(22, "who", "address"), "struct C.Bal storage ref")
    b_count = member(ident(30, "b", "struct C.Box storage pointer"), "count")
    row_amount = member(ident(31, "row", "struct C.Bal storage pointer"), "amount")
    mem_count = member(ident(40, "m", "struct C.Box memory"), "count")
    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes":
            [{
                "nodeType": "VariableDeclaration",
                "id": 10,
                "name": "box",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "struct C.Box"
                }
            }, {
                "nodeType": "VariableDeclaration",
                "id": 11,
                "name": "bal",
                "stateVariable": True,
                "typeDescriptions": {
                    "typeString": "mapping(address => struct C.Bal)"
                }
            },
             function(20, "storageAlias", [amount_param, who_param], [
                 local_decl(30, "b", "struct C.Box storage pointer", box_ident, "storage"),
                 local_decl(31, "row", "struct C.Bal storage pointer", bal_who, "storage"),
                 assign(b_count, ident(21, "amount"), "100:10:0"),
                 assign(row_amount, binop("+", row_amount, ident(21, "amount")), "120:10:0"),
                 ret(b_count, "140:10:0")
             ]),
             function(50, "memoryAlias", [amount_param], [
                 local_decl(40, "m", "struct C.Box memory", box_ident, "memory"),
                 assign(mem_count, ident(21, "amount"), "200:10:0"),
                 ret(mem_count, "220:10:0")
             ])]
        }]
    }
    layout = {"box.count": (3, 0, 32)}
    maps = {"bal.amount": (7, "address", 32, 0, "bal", "amount")}
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out_file:
        json.dump(ast, out_file)
    try:
        storage_specs, storage_evidence = source_assignment_r2_specs(path,
                                                                     "C",
                                                                     "storageAlias",
                                                                     [("amount", "uint256"),
                                                                      ("who", "address")],
                                                                     layout,
                                                                     [("amount", "num", None),
                                                                      ("who", "id", 20)],
                                                                     arity=2,
                                                                     maps=maps,
                                                                     rettypes=[("", "uint256")],
                                                                     log=lambda _msg: None)
        memory_specs, memory_evidence = source_assignment_r2_specs(path,
                                                                   "C",
                                                                   "memoryAlias",
                                                                   [("amount", "uint256")],
                                                                   layout,
                                                                   [("amount", "num", None)],
                                                                   arity=1,
                                                                   maps=maps,
                                                                   rettypes=[("", "uint256")],
                                                                   log=lambda _msg: None)
    finally:
        os.unlink(path)

    entries = {entry["name"]: entry for entry in storage_specs[0]["vars"]} if storage_specs else {}
    box_terms = [
        r2_term_text(item["term"]) for item in entries.get("box.count", {}).get("equals", [])
    ]
    row_equals = [
        r2_term_text(item["term"]) for item in entries.get("bal[who].amount", {}).get("equals", [])
    ]
    row_deltas = [
        r2_term_text(item["lo"]) for item in entries.get("bal[who].amount", {}).get("deltas", [])
    ]
    ret_terms = [
        r2_term_text(item["term"]) for item in entries.get(RETURN_VAR, {}).get("equals", [])
    ]
    bad = 0
    bad += check(box_terms == ["amount"], f"storage struct alias feeds the top-level field setter: "
                 f"{storage_specs}")
    bad += check(row_equals == ["(state.bal[who].amount + amount)"],
                 f"storage mapping-value alias feeds the exact endpoint: "
                 f"{storage_specs}")
    bad += check(row_deltas == ["amount"], f"storage mapping-value alias feeds the delta: "
                 f"{storage_specs}")
    bad += check(ret_terms == ["state.box.count"], f"storage struct alias feeds the return coord: "
                 f"{storage_specs}")
    bad += check(any("bal[who].amount: post - pre == amount" in line for line in storage_evidence),
                 f"storage alias provenance is recorded: {storage_evidence}")
    bad += check(
        memory_specs == [], f"memory aliases are not treated as state writes: "
        f"{memory_specs}, {memory_evidence}")
    return bad


