def test_same_arity_overloads_use_the_exact_path_declaration():
    from solidity_path_put import (
        function_params,
        function_returns,  # noqa: E402
        overload_artifact_label,
        select_path_claim,
        source_r2_literals)

    def declaration(node_id, parameter, param_type, ret_type, literal):
        return {
            "nodeType": "FunctionDefinition",
            "id": node_id,
            "name": "f",
            "parameters": {
                "parameters": [{
                    "name": parameter,
                    "typeDescriptions": {
                        "typeString": param_type
                    }
                }]
            },
            "returnParameters": {
                "parameters": [{
                    "name": "out",
                    "typeDescriptions": {
                        "typeString": ret_type
                    }
                }]
            },
            "body": {
                "nodeType": "Block",
                "statements": [{
                    "nodeType": "Literal",
                    "kind": "number",
                    "value": literal
                }]
            }
        }

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "C",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [
                declaration(11, "amount", "uint256", "uint256", "7"),
                declaration(12, "who", "address", "address", "9")
            ]
        }]
    }
    fd, path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out:
        json.dump(ast, out)
    try:
        params = function_params(path, "C", "f", arity=1, declaration_id=11)
        returns = function_returns(path, "C", "f", arity=1, declaration_id=11)
        literals, _ = source_r2_literals(path, "C", "f", arity=1, declaration_id=11)
        artifact_label = overload_artifact_label(path, "C", "f", 11)
    finally:
        os.unlink(path)
    report = {
        "claims": [{
            "condition": "f:path:3",
            "path_id": 3,
            "path_function": "sol:@C@C@F@f#11"
        }, {
            "condition": "f:path:3",
            "path_id": 3,
            "path_function": "sol:@C@C@F@f#12"
        }]
    }
    ambiguous, why = select_path_claim(report, "f", 3)
    exact, exact_why = select_path_claim(report, "f", 3, path_function="sol:@C@C@F@f#11")
    bad = 0
    bad += check(params == [("amount", "uint256")],
                 f"parameters come from declaration 11: {params}")
    bad += check(returns == [("out", "uint256")], f"returns come from declaration 11: {returns}")
    bad += check(literals == ["7"], f"source atoms come from declaration 11: {literals}")
    bad += check(artifact_label == "_pf11", f"overloaded artifact names carry the node id: "
                 f"{artifact_label}")
    bad += check(ambiguous is None and "multiple path functions" in why,
                 f"legacy simple-name selection refuses ambiguity: {why}")
    bad += check(exact is report["claims"][0] and exact_why is None,
                 f"the exact mangled identity selects one claim: {exact}")
    return bad


def test_synthetic_emitter_uses_inherited_empty_function_params():
    from solidity_path_put import (
        function_params,
        source_inherited_function_params,  # noqa: E402
    )

    ast = {
        "nodeType":
        "SourceUnit",
        "nodes": [{
            "nodeType":
            "ContractDefinition",
            "name":
            "GovernanceModule",
            "id":
            1,
            "linearizedBaseContracts": [1],
            "nodes": [{
                "nodeType": "FunctionDefinition",
                "id": 3207,
                "name": "feeReceiver",
                "parameters": {
                    "parameters": []
                },
                "returnParameters": {
                    "parameters": [{
                        "name": "",
                        "typeDescriptions": {
                            "typeString": "address"
                        }
                    }]
                }
            }]
        }, {
            "nodeType": "ContractDefinition",
            "name": "Governance",
            "id": 2,
            "linearizedBaseContracts": [2, 1],
            "nodes": []
        }]
    }
    source = """\
pragma solidity >=0.8.0;
contract GovernanceModule {
  function feeReceiver() public view returns (address) { return address(0); }
}
contract Governance is GovernanceModule {}
"""
    fd, ast_path = tempfile.mkstemp(suffix=".solast")
    with os.fdopen(fd, "w") as out:
        json.dump(ast, out)
    try:
        ast_params = function_params(ast_path, "Governance", "feeReceiver", None, 3207)
    finally:
        os.unlink(ast_path)
    inherited_params = source_inherited_function_params(source, "Governance", "feeReceiver", None)
    notes = []
    with tempfile.TemporaryDirectory() as out_dir:
        emitted, case = synthesize_minimal_emitted_case(out_dir,
                                                        "Governance",
                                                        "feeReceiver",
                                                        "sol:@C@Governance@F@feeReceiver#3207",
                                                        3,
                                                        inherited_params, [],
                                                        notes,
                                                        flat_source=source)
        emitted_text = open(emitted.path).read() if emitted is not None else ""
    bad = 0
    bad += check(ast_params is None, f"target-local AST lookup misses inherited unit: {ast_params}")
    bad += check(inherited_params == [], f"source inheritance fallback returns empty params: "
                 f"{inherited_params}")
    bad += check(
        emitted is not None and case is not None
        and all("unavailable" not in note for note in notes),
        f"synthetic case is built without rejecting inherited params: "
        f"emitted={emitted}, case={case}, notes={notes}")
    bad += check("c0.feeReceiver();" in emitted_text,
                 "synthetic inherited getter call is emitted with no arguments")
    return bad


def test_synthetic_inherited_params_refuse_unknown_arity_overload():
    from solidity_path_put import source_inherited_function_params  # noqa: E402
    source = """\
pragma solidity >=0.8.0;
contract Base {
  function f(uint256 amount) public view returns (uint256) { return amount; }
  function f() public view returns (uint256) { return 1; }
}
contract Derived is Base {}
"""
    bad = 0
    bad += check(
        source_inherited_function_params(source, "Derived", "f", None) is None,
        "unknown arity does not guess among inherited overloads")
    bad += check(
        source_inherited_function_params(source, "Derived", "f", 0) == [],
        "known zero arity still resolves the inherited overload")
    bad += check(
        source_inherited_function_params(source, "Derived", "f", 1) == [("amount", "uint256")],
        "known single-arg arity resolves the inherited overload")
    source = """\
pragma solidity >=0.8.0;
contract A { function f() public view returns (uint256) { return 1; } }
contract B { function f(uint256 amount) public view returns (uint256) { return amount; } }
contract D is A, B {}
"""
    bad += check(
        source_inherited_function_params(source, "D", "f", None) is None,
        "unknown arity does not guess among overloads inherited from different bases")
    return bad


