def test_structured_R2_interval_accepts_literal_endpoint_without_lookup():
    """Mixed intervals should not require a redundant literal term entry."""
    from solidity_path_put import rung_assertions  # noqa: E402
    term = {
        "kind": "op",
        "op": "add",
        "lhs": {
            "kind": "pre"
        },
        "rhs": {
            "kind": "coord",
            "name": "msg.value"
        }
    }
    got = rung_assertions("post in [0, (pre + msg.value)]", "_pre_bal", "_post_bal", "bal: abs",
                          {"msg.value": "0"}, {"msg.value": "0"}, {"(pre + msg.value)": term})
    bad = 0
    bad += check(
        got == [
            '    assertGe(_post_bal, 0, "bal: abs");', '    unchecked { assertLe(_post_bal, '
            '(uint256(_pre_bal) + uint256(0)), "bal: abs"); }'
        ], f"literal low endpoint and structured high endpoint both render: {got}")
    refused = rung_assertions("post in [floor, (pre + msg.value)]", "_pre_bal", "_post_bal",
                              "bal: abs", {"msg.value": "0"}, {"msg.value": "0"},
                              {"(pre + msg.value)": term})
    bad += check(refused is None, f"a non-literal endpoint still needs a certified term: "
                 f"{refused}")
    return bad


