    bad += check(any("assertTrue(_post_feeReceiver != _pre_feeReceiver" in ln for ln in put),
                 "the change assertion IS rendered on a bare call")
    bad += check(not any("REVERT-TOLERANT" in s for s in stats["oracle_skipped"]),
                 f"and nothing is dropped for tolerance: "
                 f"{stats['oracle_skipped']}")
    return bad


