def test_authenticated_concrete_oracle_downgrade_fails_closed():
    completion = {
        "class": "R0",
        "kind": "normal-exit",
        "observed": "_veriput_concrete_completed",
        "expected": True,
        "provenance": "stage2-witness",
        "target_receiver": "c0",
        "assertion": "assertTrue(_veriput_concrete_completed);",
    }
    exact_return = {
        "class": "R0",
        "kind": "return-value",
        "solidity_type": "uint8",
        "observed": "observed",
        "expected": "uint8(7)",
        "provenance": "stage2-witness",
        "target_receiver": "c0",
        "assertion": "assertEq(observed, uint8(7));",
    }
    bad = 0
    bad += check(
        "normal-exit cannot downgrade"
        in str(authenticated_concrete_oracle_error([completion, exact_return])),
        "completion cannot replace or accompany an exact return")
    for damaged in ({
            **exact_return, "kind": "unknown"
    }, {
            key: value
            for key, value in exact_return.items() if key != "expected"
    }, {
            **exact_return, "assertion": ""
    }, {
            **exact_return, "provenance": "guessed"
    }):
        bad += check(
            authenticated_concrete_oracle_error([damaged]) is not None,
            "missing or unauthenticated structured evidence fails closed")
    source = "contract C { function test_cov_0() public { c0.f(); } }"
    unchanged, retained, error = reuse_authenticated_concrete_oracles(source, "test_cov_0", "f",
                                                                      [exact_return])
    bad += check(unchanged == source and retained == [] and error is not None,
                 "metadata cannot claim an assertion absent from the replay")
    unrelated_source = ('contract C { function test_cov_0() public { c0.f(); '
                        'assertEq(helper.value(), uint256(7)); } }')
    unrelated = [{
        "class": "concrete-value",
        "kind": "post-state",
        "observed": "helper.value()",
        "expected": "uint256(7)",
        "provenance": "stage2-witness",
        "target_receiver": "helper",
        "assertion": "assertEq(helper.value(), uint256(7));",
    }]
    unchanged, retained, error = reuse_authenticated_concrete_oracles(unrelated_source,
                                                                      "test_cov_0", "f", unrelated)
    bad += check(unchanged == unrelated_source and retained == [] and error is not None,
                 "an unrelated helper assertion cannot authenticate the target call")
    untyped_exact = """contract C {
  function test_cov_0() public {
    c0.f();
    assertEq(c0.value(), 7);
  }
}
"""
    unchanged, retained = add_concrete_normal_exit_oracle(untyped_exact, "test_cov_0", "f")
    bad += check(unchanged == untyped_exact and retained == [],
                 "an untyped exact assertion is refused instead of downgraded")
    scalar_oracle = [{"kind": "return-value", "expected": "uint8(8)"}]
    bad += check("differs" in _oracle_claim_coverage_error({"return_value": "7"}, scalar_oracle),
                 "wrong scalar expected value is rejected")
    revert_claim = {"return_value": "true", "exit_kind": "revert",
                    "representative_claim_exit_kind": "normal"}
    bad += check(
        _oracle_claim_coverage_error(revert_claim, [{"kind": "call-status", "expected": False}])
        is None,
        "a harvested return value on a REVERTING path needs no return-value oracle when the "
        "call status is asserted")
    bad += check(
        "lacks an exact return-value oracle" in (_oracle_claim_coverage_error(
            revert_claim, [{"kind": "post-state", "expected": "0"}]) or ""),
        "without a call-status oracle the harvested return value still demands coverage")
    bad += check(
        "lacks an exact return-value oracle" in (_oracle_claim_coverage_error(
            {"return_value": "true", "exit_kind": "normal"},
            [{"kind": "call-status", "expected": True}]) or ""),
        "a NORMAL exit still demands the return-value oracle")
    foundry_observed = [{
        "kind": "return-value",
        "expected": "uint8(18)",
        "source": "foundry-fixed-replay",
    }]
    bad += check(
        _oracle_claim_coverage_error({
            "return_value": "0",
            "exit_kind": "normal"
        }, foundry_observed) is None,
        "a fixed replay return observed by Foundry is not compared to the model witness")
    bad += check(
        _oracle_claim_coverage_error({"return_value": "reportSymbol"}, [{
            "kind": "return-value",
            "expected": "differentSymbol"
        }]) is not None,
        "different unrenderable scalar texts cannot compare equal")
    tuple_oracles = [{
        "kind": "return-value",
        "return_index": index,
        "return_arity": 2,
        "expected": expected,
    } for index, expected in enumerate(("uint8(1)", "uint16(9)"))]
    bad += check(
        "differs" in _oracle_claim_coverage_error({"return_value": "(1,2)"}, tuple_oracles),
        "wrong tuple component is rejected")
    bad += check(
        "differs" in _oracle_claim_coverage_error({
            "exit_kind": "normal",
            "events": [{
                "name": "Expected"
            }]
        }, [{
            "kind": "event-log",
            "expected": {
                "name": "Other"
            }
        }]), "wrong event sequence is rejected")
    bad += check(
        "differs" in _oracle_claim_coverage_error({"call_status": False}, [{
            "kind": "call-status",
            "expected": True
        }]), "wrong call status is rejected")
    bad += check(
        "normal exit" in _oracle_claim_coverage_error({"exit_kind": "normal"}, [{
            "kind": "call-status",
            "expected": False
        }]), "normal exit rejects a failed target call status without report status metadata")
    bad += check(
        "differs" in _oracle_claim_coverage_error({"revert_selector": "0x12345678"},
                                                  [{
                                                      "kind": "revert",
                                                      "expected": "0x87654321"
                                                  }]), "wrong revert selector is rejected")
    exact_event = {
        "kind": "event-log",
        "expected": {
            "log_count": 1,
            "event_index": 0,
            "emitter": "address(c0)",
            "topics": ['keccak256("Updated(address,uint256)")'],
            "data": "abi.encode(uint256(9))",
        },
    }
    bad += check(
        _oracle_claim_coverage_error(
            {
                "exit_kind": "normal",
                "events": ["sol:@C@Probe@F@Updated#42"],
            }, [exact_event], {42: "Updated(address,uint256)"}) is None,
        "event declaration identity maps to the exact event-log signature")
    bad += check(
        "event declaration" in _oracle_claim_coverage_error(
            {
                "exit_kind": "normal",
                "events": ["sol:@C@Probe@F@Updated#42"],
            }, [{
                **exact_event, "expected": {
                    **exact_event["expected"],
                    "topics": ['keccak256("Updated(address,address)")'],
                }
            }], {42: "Updated(address,uint256)"}),
        "same-name overloaded event cannot use another declaration signature")
    bad += check(
        "event declaration" in _oracle_claim_coverage_error(
            {
                "exit_kind": "normal",
                "events": ["sol:@C@Probe@F@Transfer#44"],
            }, [{
                **exact_event, "expected": {
                    **exact_event["expected"],
                    "topics": ['keccak256("OtherTransfer(bytes32)")'],
                }
            }], {44: "Transfer(bytes32)"}),
        "an event signature substring cannot impersonate the declaration")
    return bad


def test_concrete_return_witness_is_restricted_to_certified_basis():
    bad = 0
    bad += check(
        concrete_return_mode_allowed(True, "certified-region-concrete-fallback",
                                     "CERTIFIED-BASIS-REPLAY"),
        "the retained certified basis may consume its return witness")
    for concrete_only, source, witness_check in ((False, "certified-region-concrete-fallback",
                                                  "CERTIFIED-BASIS-REPLAY"),
                                                 (True, "no-coordinate-concrete-fallback",
                                                  "CERTIFIED-BASIS-REPLAY"),
                                                 (True, "certified-region-concrete-fallback",
                                                  "SUCCESSFUL")):
        bad += check(not concrete_return_mode_allowed(concrete_only, source, witness_check),
                     "other Stage-4 modes cannot inject a return witness")
    return bad


def test_known_nonvoid_certified_basis_requires_return_witness():
    bad = 0
    bad += check(
        certified_basis_missing_return_witness(True, "certified-region-concrete-fallback",
                                               "CERTIFIED-BASIS-REPLAY", [("", "uint8")], None),
        "known non-void certified basis refuses a missing witness")
    bad += check(
        not certified_basis_missing_return_witness(True, "certified-region-concrete-fallback",
                                                   "CERTIFIED-BASIS-REPLAY", [], None),
        "void certified basis does not require a return witness")
    bad += check(
        not certified_basis_missing_return_witness(True, "certified-region-concrete-fallback",
                                                   "CERTIFIED-BASIS-REPLAY", None, None),
        "unknown return metadata is not mislabeled non-void")
    bad += check(
        not certified_basis_missing_return_witness(True, "certified-region-concrete-fallback",
                                                   "CERTIFIED-BASIS-REPLAY", [("", "uint8")], "0"),
        "known non-void certified basis accepts an exact witness")
    bad += check(
        not certified_basis_missing_return_witness(
            True,
            "certified-region-concrete-fallback",
            "CERTIFIED-BASIS-REPLAY", [("", "uint8")],
            None,
            concrete_oracles=[{
                "kind": "post-state",
                "observed": "c0.value()",
                "expected": 7,
                "provenance": "stage2-witness",
                "assertion": "assertEq(c0.value(), 7);",
            }]), "an exact structured state oracle need not be downgraded to a return oracle")
    bad += check(
        not certified_basis_missing_return_witness(
            True, "certified-region-concrete-fallback", "CERTIFIED-BASIS-REPLAY", [("", "uint8")],
            None, "abi-value-gate"), "nonpayable ABI value-gate basis is a call-status replay, "
        "not a return-value replay")
    bad += check(
        not certified_basis_missing_return_witness(True, "certified-region-concrete-fallback",
                                                   "CERTIFIED-BASIS-REPLAY", [("", "address")],
                                                   None, "getter-value-gate"),
        "nonpayable getter value-gate basis is a call-status replay, "
        "not a return-value replay")
    bad += check(
        not certified_basis_missing_return_witness(True,
                                                   "certified-region-concrete-fallback",
                                                   "CERTIFIED-BASIS-REPLAY", [("", "uint256")],
                                                   None,
                                                   region={"msg.value": (1, UINT256_MAX)}),
        "certified msg.value gate basis is a call-status replay even "
        "when the target function returns a value")
    bad += check(
        certified_basis_missing_return_witness(True,
                                               "certified-region-concrete-fallback",
                                               "CERTIFIED-BASIS-REPLAY", [("", "uint256")],
                                               None,
                                               region={"msg.value": (0, UINT256_MAX)}),
        "a non-void basis without a positive value gate still "
        "requires an exact return witness")
    return bad


def test_concrete_replay_preserves_low_level_call_status_oracle():
    source = '''contract CReplay is Test {
  function test_cov_0() public {
    (bool ok,) = address(c0).call{value: 1}(
        abi.encodeWithSignature("f()"));
    assertFalse(ok, "nonpayable call must revert");
  }
}
'''
    rewritten, oracles = add_concrete_normal_exit_oracle(source, "test_cov_0", "f")
    bad = 0
    bad += check(rewritten == source,
                 "the concrete producer does not rewrite an existing call-status oracle")
    bad += check(
        oracles == [{
            "class": "R0",
            "kind": "call-status",
            "observed": "ok",
            "expected": False,
            "provenance": "stage2-witness",
            "target_receiver": "c0",
            "assertion": 'assertFalse(ok, "nonpayable call must revert");',
        }], f"the low-level result is bound to the fixed target call: {oracles}")
    no_status = source.replace('    assertFalse(ok, "nonpayable call must revert");\n', '')
    unchanged, missing = add_concrete_normal_exit_oracle(no_status, "test_cov_0", "f")
    bad += check(unchanged == no_status and missing == [],
                 "a low-level call without a status oracle is refused, not marked complete")
    prior = source.replace('    (bool ok,)', '    bool prior = false;\n    (bool ok,)')
    unchanged, bound = add_concrete_normal_exit_oracle(prior, "test_cov_0", "f")
    bad += check(bound and bound[0]["observed"] == "ok",
                 "an unrelated earlier bool cannot replace the call status")
    commented = source.replace('    (bool ok,)', '    // fixed low-level witness\n    (bool ok,)')
    unchanged, bound = add_concrete_normal_exit_oracle(commented, "test_cov_0", "f")
    bad += check(bound and bound[0]["observed"] == "ok",
                 "a leading comment cannot hide the exact low-level call status")
    return bad


def test_assembled_concrete_source_refuses_unsupported_replay():
    """A green empty replay is not a reference test."""
    emitted = """\
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {BoxUser} from "./BoxUser.sol";

contract BoxUserCovTest is Test {
  BoxUser c0;
  function setUp() public {
    c0 = new BoxUser();
  }
  // claim: sol:@C@BoxUser@F@put#9:path:4
  function test_cov_0() public {
    // UNSUPPORTED: BoxUser.put has an argument type ESBMC cannot yet render as a literal
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@BoxUser@F@put#9", 4)
    bad = 0
    try:
        assemble_concrete_source(em, case, "BoxUserCovTest_BoxUser_put_concrete4", unit="put")
        refused = None
    except ValueError as exc:
        refused = str(exc)
    bad += check(refused is not None and "UNSUPPORTED" in refused,
                 f"unsupported concrete replay is refused: {refused}")
    return bad


def test_assembled_concrete_source_completes_missing_call_args():
    """A bad concrete replay must not poison a neighbouring PUT project."""
    emitted = """\
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "./C.sol";

contract CCovTest_0 is Test {
  C c0;
  function setUp() public {
    c0 = new C();
  }
  // claim: sol:@C@C@F@f#9:path:4
  function test_cov_0() public {
    try c0.f() {} catch {}
    c0.f();
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@C@F@f#9", 4)
    text = assemble_concrete_source(em,
                                    case,
                                    "CCovTest_C_f_concrete4",
                                    unit="f",
                                    params=[("a", "address"), ("b", "uint256"), ("c", "uint256")])
    bad = 0
    completed = "c0.f(address(uint160(0)), 0, 0)"
    bad += check(text.count(completed) == 2, "all omitted concrete replay arguments are completed")
    bad += check("c0.f()" not in text, "the uncompilable zero-argument calls are gone")
    bad += check("function test_put_" not in text,
                 "the repaired concrete replay is still not a PUT")
    return bad


def test_certified_value_gate_basis_concrete_uses_low_level_call():
    """A certified nonpayable value-gate basis must exercise that gate."""
    emitted = """\
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {OwnerGate} from "./OwnerGate.sol";

contract OwnerGateCovTest is Test {
  OwnerGate c0;
  function setUp() public {
    c0 = new OwnerGate();
  }
  // claim: sol:@C@OwnerGate@F@transferOwnership#9:path:2
  function test_cov_0() public {
    vm.prank(address(uint160(0)));
    c0.transferOwnership(address(uint160(2000)));
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@OwnerGate@F@transferOwnership#9", 2)
    text = assemble_concrete_source(em,
                                    case,
                                    "OwnerGateCovTest_OwnerGate_transferOwnership_concrete2",
                                    contract="OwnerGate",
                                    unit="transferOwnership",
                                    params=[("newOwner", "address")],
                                    region={
                                        "msg.value": (1, UINT256_MAX),
                                        "msg.sender": (0, (1 << 160) - 1),
                                    },
                                    pins={},
                                    certified_value_gate_basis=True)
    bad = 0
    bad += check("function test_cov_0()" in text, "the basis remains a concrete replay test")
    bad += check("function disabled_test_cov_0()" not in text,
                 "the selected replay is not pre-disabled")
    bad += check("vm.deal(address(uint160(1)), 1);" in text,
                 "the concrete sender is funded inside the certified sender range")
    bad += check("vm.prank(address(uint160(1)));" in text,
                 "the concrete sender avoids Foundry's unprankable zero address")
    bad += check(
        "address(c0).call{value: 1}(abi.encodeWithSignature("
        "\"transferOwnership(address)\", address(uint160(2000))))" in text,
        "the high-level nonpayable call is rewritten as value-bearing low-level ABI call")
    bad += check("assertFalse(_esbmc_value_gate_ok" in text,
                 "the value-gate exit is asserted on the low-level call result")
    bad += check("c0.transferOwnership(" not in text,
                 "the stale high-level call no longer stands for the value-gate path")
    return bad


def test_certified_value_gate_basis_drops_stale_revert_prelude():
    """The low-level value-gate call consumes its own prank and status oracle."""
    emitted = """\
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test} from "forge-std/Test.sol";
import {OwnerGate} from "./OwnerGate.sol";

contract OwnerGateCovTest is Test {
  OwnerGate c0;
  function setUp() public {
    c0 = new OwnerGate();
  }
  // claim: sol:@C@OwnerGate@F@transferOwnership#9:path:2
  function test_cov_0() public {
    vm.prank(address(uint160(0)));
    vm.expectRevert(abi.encodeWithSelector(bytes4(keccak256("E_CheckUnauthorized()"))));
    c0.transferOwnership(address(uint160(2000)));
  }
}
"""
    fd, path = tempfile.mkstemp(suffix=".cov.t.sol")
    with os.fdopen(fd, "w") as f:
        f.write(emitted)
    try:
        em = EmittedFile(path)
    finally:
        os.unlink(path)
    case = em.case_for("sol:@C@OwnerGate@F@transferOwnership#9", 2)
    text = assemble_concrete_source(em,
                                    case,
                                    "OwnerGateCovTest_OwnerGate_transferOwnership_concrete2",
                                    contract="OwnerGate",
                                    unit="transferOwnership",
                                    params=[("newOwner", "address")],
                                    region={
                                        "msg.value": (1, UINT256_MAX),
                                        "msg.sender": (0, (1 << 160) - 1),
                                    },
                                    pins={},
                                    certified_value_gate_basis=True)
    body = text[text.find("function test_cov_0() public {"):text.
                find("}\n}", text.find("function test_cov_0() public {"))]
    bad = 0
    bad += check("vm.expectRevert" not in body,
                 "the stale high-level revert oracle is removed before the low-level call")
    bad += check("vm.prank(address(uint160(0)))" not in body,
                 "the stale high-level prank is removed before the low-level call")
    bad += check(
        body.count("vm.prank(") == 1 and "vm.prank(address(uint160(1)));" in body,
        "only the value-gate sender prank remains")
    bad += check("assertFalse(_esbmc_value_gate_ok" in body,
                 "the low-level call status remains the execution oracle")
    return bad


def test_certified_value_gate_basis_materializes_exact_ce_sender_and_value():
    lines = [
        "  function test_cov_0() public {",
        "    vm.prank(address(uint160(99)));",
        "    c0.f(uint256(7));",
        "  }",
    ]
    rendered, changed, reason = materialize_concrete_nonpayable_value_gate(
        lines, "f", [("amount", "uint256")], {
            "msg.value": (1, 100),
            "msg.sender": (0, 100),
        }, {}, {
            "amount": "7",
            "msg.sender": "3",
            "msg.value": "11",
        })
    source = "\n".join(rendered)
    bad = 0
    bad += check(changed == 1 and reason is None,
                 f"the exact certified gate CE is renderable: {reason}")
    bad += check("vm.deal(address(uint160(3)), 11);" in source,
                 "the exact certified sender receives the exact certified value")
    bad += check("vm.prank(address(uint160(3)));" in source,
                 "the exact certified sender drives the call")
    bad += check("call{value: 11}" in source and ", uint256(7)))" in source,
                 "the exact certified value and argument reach the ABI call")
    zero_sender, changed, reason = materialize_concrete_nonpayable_value_gate(
        lines, "f", [("amount", "uint256")], {
            "msg.value": (1, 100),
            "msg.sender": (1, 100),
        }, {}, {
            "amount": "7",
            "msg.sender": "0",
            "msg.value": "11",
        })
    bad += check(
        changed == 1 and reason is None
        and "vm.prank(address(uint160(1)));" in "\n".join(zero_sender),
        "the structural gate projects zero before checking Foundry's renderable domain")
    _rendered, changed, reason = materialize_concrete_nonpayable_value_gate(
        lines, "f", [("amount", "uint256")], {
            "msg.value": (1, 10),
        }, {}, {
            "amount": "7",
            "msg.sender": "3",
            "msg.value": "11",
        })
    bad += check(changed == 0 and "outside" in reason,
                 "a certified CE outside its certified gate region fails closed")
    return bad


def test_concrete_value_gate_uses_fresh_status_identifiers():
    lines = [
        "  function test_cov_0() public {",
        "    c0.f();",
        "    c0.f();",
        "  }",
    ]
