def test_certified_basis_materializes_mapping_keyed_by_another_state_variable():
    em, case = make_case()
    source = "\n".join(em.lines) + "\n"
    certified_ce = {
        "u": "0",
        "bps": "250",
        "state.owner": "0",
        "state._ownerAddress$5604": "730750818665451459101842416358141509832261238783",
        "state.isAdmin$5630[(&_ESBMC_Object_MergingPool)->_ownerAddress$5604]": "1",
    }
    layout = dict(LAYOUT)
    layout["_ownerAddress"] = (2, 0, 20)
    maps = {"isAdmin$5630": (3, "address", 1, 0, "isAdmin", None),
            "isAdmin": (3, "address", 1, 0, "isAdmin", None)}
    rendered, changed, reason = materialize_concrete_certified_state_point(
        source, case[1], "setDiscount", certified_ce, layout, maps=maps)
    body = "\n".join(function_body_lines(rendered, case[1]) or [])
    bad = 0
    bad += check(reason is None and changed >= 4,
                 f"a mapping keyed by another state variable is materialized: {reason}")
    bad += check("730750818665451459101842416358141509832261238783" in body
                 and "keccak256" in body,
                 "the slot is keccak(<the CE value of that state variable>, base slot)")
    cast_ce = dict(certified_ce)
    cast_ce["state.isAdmin$5630[(unsigned _ExtInt(256))(&_ESBMC_Object_MergingPool)"
            "->_ownerAddress$5604]"] = cast_ce.pop(
                "state.isAdmin$5630[(&_ESBMC_Object_MergingPool)->_ownerAddress$5604]")
    _r2, _c2, cast_reason = materialize_concrete_certified_state_point(
        source, case[1], "setDiscount", cast_ce, layout, maps=maps)
    bad += check(cast_reason is None, f"the width-cast spelling of the key resolves too: {cast_reason}")
    _r, _c, missing = materialize_concrete_certified_state_point(
        source, case[1], "setDiscount",
        {k: v for k, v in certified_ce.items() if k != "state._ownerAddress$5604"},
        layout, maps=maps)
    bad += check(missing is not None and "does not fix" in missing,
                 "a key state variable the CE does not fix still refuses")
    return bad


def test_certified_call_point_keeps_dynamic_arguments_the_ce_never_mentions():
    source = """contract T is Test {
  F c0;
  function setUp() public { c0 = new F(); }
  function test_cov_1() public {
    vm.prank(address(uint160(1)));
    c0.f("abc", 7);
  }
}
"""
    params = [("description", "string calldata"), ("x", "uint256")]
    kept, n, reason = materialize_concrete_certified_call_point(
        source, "test_cov_1", "f", params, {"x": "7", "msg.sender": "1"})
    bad = 0
    bad += check(reason is None and 'c0.f("abc", uint256(7));' in kept,
                 f"a string the CE never mentions keeps the emitter's literal: {reason}")
    empty, _n, reason_empty = materialize_concrete_certified_call_point(
        source, "test_cov_1", "f", params, {"x": "7", "description.length": "0"})
    bad += check(reason_empty is None and 'c0.f("", uint256(7));' in empty,
                 f"a string the CE fixes at length 0 renders as the empty string: {reason_empty}")
    _r, _n2, reason_read = materialize_concrete_certified_call_point(
        source, "test_cov_1", "f", params, {"x": "7", "description.length": "3"})
    bad += check(reason_read is not None and "cannot be rendered exactly" in reason_read,
                 "a string the CE constrains to a nonzero length still refuses")
    _r2, _n3, reason_scalar = materialize_concrete_certified_call_point(
        source, "test_cov_1", "f", params, {"msg.sender": "1"})
    bad += check(reason_scalar is not None and "`x`" in reason_scalar,
                 "a scalar the CE does not fix still refuses")
    return bad


def test_certified_call_point_renders_dynamic_arrays_like_bytes():
    """`address[] memory` at certified length 0 -> `new address[](0)`; unmentioned
    arrays keep the emitter's literal; the binder accepts both (rc_unchecked
    0x2972/0x4051 transfer, full-20260822-v40 round 10)."""
    source = """contract T is Test {
  F c0;
  function setUp() public { c0 = new F(); }
  function test_cov_1() public {
    vm.prank(address(uint160(1)));
    c0.transfer(address(uint160(5700)), new address[](4), 7);
  }
}
"""
    params = [("from", "address"), ("_tos", "address[] memory"), ("v", "uint256")]
    empty, _n, reason_empty = materialize_concrete_certified_call_point(
        source, "test_cov_1", "transfer", params, {"from": "0", "v": "7", "_tos.length": "0"})
    bad = 0
    bad += check(reason_empty is None and
                 'c0.transfer(address(uint160(0)), new address[](0), uint256(7));' in empty,
                 f"an array the CE fixes at length 0 renders as the empty array: {reason_empty} / {empty}")
    kept, _n2, reason_kept = materialize_concrete_certified_call_point(
        source, "test_cov_1", "transfer", params, {"from": "0", "v": "7"})
    bad += check(reason_kept is None and "new address[](4)" in kept,
                 f"an array the CE never mentions keeps the emitter's literal: {reason_kept}")
    _r, _n3, reason_read = materialize_concrete_certified_call_point(
        source, "test_cov_1", "transfer", params, {"from": "0", "v": "7", "_tos.length": "2"})
    bad += check(reason_read is not None and "cannot be rendered exactly" in reason_read,
                 "an array the CE constrains to a nonzero length still refuses")
    # binder on the rendered empty array
    body = function_body_lines(empty, "test_cov_1")
    call_i = find_unit_call(body, "transfer")
    audit = {}
    digest, bind_error = bind_emitted_source_to_certified_ce(
        body, call_i, "transfer", params,
        {"from": "0", "v": "7", "_tos.length": "0", "msg.sender": "1"}, audit=audit)
    bad += check(digest is not None and bind_error is None,
                 f"the empty array binds as the CE's `_tos.length = 0`: {bind_error}")
    return bad


