def test_commented_out_constructor_is_not_a_constructor():
    # `peer_soltg__exampl` declares no constructor; the only `constructor(`
    # text in the file is commented out.  Reading its parameter list emitted
    # `new A(0)` and the whole subject failed to compile, so it produced no
    # valid test at all.
    source = ("contract A{\n"
              "  uint a;\n"
              "//  constructor(uint i) {a = i;}\n"
              "  function set(uint j) public {a = j;}\n"
              "}\n")
    assert solidity_path_put._source_constructor_params_from_source(source, "A") == []


def test_a_real_constructor_still_parses_past_a_commented_one():
    source = ("contract B{\n"
              "  /* constructor(uint q) {} */\n"
              "  // constructor(uint z) {}\n"
              "  constructor(address a, uint b) {}\n"
              "}\n")
    assert solidity_path_put._source_constructor_params_from_source(source, "B") == [
        ("a", "address"), ("b", "uint256")]


def test_struct_literal_entry_storage_flattens_to_certified_ce_members():
    """ESBMC prints a storage struct as `{ .m = v }`; the certified CE is flat."""
    from solidity_path_put import _struct_literal_members, claim_concrete_ce
    assert _struct_literal_members("{ .currentRound = 0 }") == {"currentRound": 0}
    assert _struct_literal_members("{ .a = { .b = 1, .c = 0x2 }, .d = 3 }") == {
        "a.b": 1, "a.c": 2, "d": 3}
    assert _struct_literal_members("{ }") == {}
    assert _struct_literal_members("{ .a = foo }") is None
    assert _struct_literal_members("not a struct") is None
    claim = {"inputs": {"account": "0"}, "env": {},
             "entry_storage": {"vaultBatchingState": "{ .currentRound = 0 }",
                               "vaultBatchingState.currentRound": "0", "keeper": "0"}}
    assert claim_concrete_ce(claim) == {"account": 0, "state.vaultBatchingState.currentRound": 0,
                                        "state.keeper": 0}
    conflicting = {"inputs": {}, "env": {},
                   "entry_storage": {"s": "{ .x = 1 }", "s.x": "2"}}
    assert claim_concrete_ce(conflicting) is None


def test_bytesn_literal_maps_to_the_certified_ce_scalar():
    """ESBMC prints bytesN as `{ .data={...}, .length=N }`; the CE is an int."""
    from solidity_path_put import _bytesn_literal_value, claim_concrete_ce
    assert _bytesn_literal_value("{ .data = { 0 } }") == 0
    assert _bytesn_literal_value("{ .data={ 0, 0 }, .length=32 }") == 0
    assert _bytesn_literal_value("{ .data={ 1 }, .length=32 }") == 1 << (31 * 8)
    assert _bytesn_literal_value("{ .data={ 0, 1 }, .length=2 }") == 1
    assert _bytesn_literal_value("{ .data={ 255, 255 }, .length=2 }") == 0xFFFF
    # width unknown and non-zero: refuse rather than guess
    assert _bytesn_literal_value("{ .data = { 1 } }") is None
    # not a bytesN spelling
    assert _bytesn_literal_value("{ .currentRound = 0 }") is None
    assert _bytesn_literal_value("{ .data={ 300 }, .length=1 }") is None
    # a non-zero byte BEYOND the length is not a bytesN value
    assert _bytesn_literal_value("{ .data={ 1, 2 }, .length=1 }") is None
    # the 32-byte BytesStatic buffer printed whole for a bytes16 (LiquidityPool
    # trancheId, 2026-08-22): value in data[0..15], zero tail
    assert _bytesn_literal_value("{ .data={ " + ", ".join(["0"] * 32) + " }, .length=16 }") == 0
    assert _bytesn_literal_value("{ .data={ 0, 1" + ", 0" * 30 + " }, .length=16 }") == 1 << (14 * 8)
    assert _bytesn_literal_value("{ .data={ " + "0, " * 31 + "7 }, .length=16 }") is None
    claim = {"inputs": {"assertionId": "{ .data = { 0 } }", "who": "2001"},
             "env": {}, "entry_storage": {}}
    assert claim_concrete_ce(claim) == {"assertionId": 0, "who": 2001}
    # a symbolic mapping key the certified CE fixes is the witness's literal key
    # (LiquidityPool.rely, 2026-08-22): the binder renames the witness spelling
    from solidity_path_put import bind_emitted_claim_to_certified_ce
    expected = {"msg.sender": "7", "state.wards$5[msg.sender]": "1"}
    claim = {"inputs": {}, "env": {"msg.sender": "7"}, "entry_storage": {"wards$5[7]": "1"}}
    bound, err = bind_emitted_claim_to_certified_ce(claim, expected)
    assert err is None and bound["status"] == "exact", err
    claim_other = {"inputs": {}, "env": {"msg.sender": "7"}, "entry_storage": {"wards$5[8]": "1"}}
    bound, err = bind_emitted_claim_to_certified_ce(claim_other, expected)
    assert bound is None and "wards$5[8]" in err, err
    # the oracle-part representative CE reads bytesN / struct state like the
    # binder does (LiquidityPool.trancheId, 2026-08-22)
    from solidity_path_put import claim_oracle_ce_values
    claim_b16 = {"inputs": {"assets": "5"}, "env": {"msg.sender": "0"},
                 "entry_storage": {"trancheId": "{ .data={ " + ", ".join(["0"] * 32) + " }, .length=16 }",
                                   "s": "{ .currentRound = 3 }"}}
    assert claim_oracle_ce_values(claim_b16) == {"assets": "5", "msg.sender": "0",
                                                 "state.trancheId": "0", "state.s.currentRound": "3"}
    assert claim_oracle_ce_values({"inputs": {"x": "{ .data={ 1 } }"}, "env": {}, "entry_storage": {}}) is None


def test_oracle_part_query_plan_names_every_r1_variable_once():
    from solidity_path_put import oracle_part_query_plan, oracle_part_assert_spec
    fams = [(("x", "post > pre"), "R1"), (("y", "post == pre"), "R1"),
            (("x", "post < pre"), "R1"), (("z", "post in [0, 1]"), "R2.3")]
    exact = {("z", "post in [0, 1]"): [{"name": "z", "abs": [{"id": "a0", "lo": "0", "hi": "1"}]}]}
    sig, kw = oracle_part_query_plan(("x", "post < pre"), fams, exact, lambda n: "state." + n)
    assert sig == ("state-exact", ("state.x", "state.y"))
    assert kw == {"variables": ["state.x", "state.y"]}
    # every R1 candidate of the row maps to the SAME signature -> one process per part
    sig2, _ = oracle_part_query_plan(("y", "post == pre"), fams, exact, lambda n: "state." + n)
    assert sig2 == sig
    sigz, kwz = oracle_part_query_plan(("z", "post in [0, 1]"), fams, exact, lambda n: "state." + n)
    assert sigz[0] == "exact" and kwz == {"exact_vars": exact[("z", "post in [0, 1]")]}
    spec = oracle_part_assert_spec({"region": []}, _oracle_part_fixture(), **kw)
    assert spec["vars_policy"] == "state-exact"
    assert [v["name"] for v in spec["vars"]] == ["state.x", "state.y"]


def _oracle_part_fixture():
    from solidity_path_put import make_oracle_input_part
    return make_oracle_input_part("part0", {"a": (0, 10)}, {}, {"a": 3})

